/* 江湖一生 · incidents: the dark factions (dk_) and wuxia legends (wx_) */
'use strict';

/* ====================== helpers ====================== */
const DK_LORD={sunmoon:T('the Crimson Lord','赤霄教主'),wudu:T('the Venom Mother','五毒教主'),xingxiu:T('the Old Patriarch of the Seven Fiends','七煞老祖'),xuedao:T('the Red Blade Ancestor','赤刃老祖'),erengu:T('the Ten Fiends of the valley','谷中十凶'),qinglong:T('the Owl Head','夜枭老大'),jinqian:T('the Coin Master','通宝帮主'),haisha:T('the Black Tide chief','黑潮帮主'),tiequan:T('the Iron Fist chief','铁拳帮主'),feiying:T('the Flying Hawk chief','飞鹰帮主'),tuoling:T('the master of Camel Bell Manor','驼铃庄主'),haijiao:T('the Sea Serpent Lord','海蛟教主')};
const dkL=s=>DK_LORD[s.sect]||T('the lord','教主');
const dkS=s=>s.sect&&SECTS[s.sect]?T(SECTS[s.sect].en,SECTS[s.sect].cn):T('the faction','本教');
const dkEv=s=>isEvil(s.sect);
const dkRt=s=>!!s.sect&&!isEvil(s.sect);
const dkOld=s=>{const k=s.dkFrom||s.flags.formerSect;return k&&SECTS[k]&&SECTS[k].evil?T(SECTS[k].en,SECTS[k].cn):T('your old faction','你背弃的那个邪派')};
const dkRivalK=s=>pick(Object.keys(SECTS).filter(k=>SECTS[k].evil&&k!==s.sect));
const dkRightK=()=>pick(['shaolin','wudang','emei','huashan','kunlun','quanzhen','songshan','qingcheng','kongtong','taishan']);
const dkST=k=>T(SECTS[k].en,SECTS[k].cn);
const dkSus=p=>s=>{if(chance(p))s.flags.dk_suspect=s.age};
const dkJoin=k=>s=>{if(!s.sect&&SECTS[k]){joinSect(s,k);s.align=clamp(s.align-5,-100,100)}};
const dkFree=s=>!s.sect&&!s.org&&s.jail<=0;
/* leaving a dark faction: remember which one, and the Crimson Sky Cult’s pill stays in your gut */
(()=>{const f0=leaveSect;leaveSect=function(s){const was=s.sect;f0(s);if(isEvil(was)){s.dkFrom=was;if(was==='sunmoon')s.flags.dk_pill=s.age}}})();
/* punishments are meant to hurt, not to kill: a "soft" wound never takes the last few points of health */
(()=>{const f0=applyFx;applyFx=function(s,e,c){if(e&&e.soft&&e.hurt){const m=Math.max(1,s.health-8);e=Object.assign({},e,{hurt:[Math.min(e.hurt[0],m),Math.min(e.hurt[1],m)]})}f0(s,e,c)}})();
QHINT.dk_pill={t:T('The Heart-Eating Pill sleeps in your gut. Without the yearly antidote it will wake.','腹中的噬心丹没有每年的解药压着，迟早要发作。'),done:'dk_pillwake'};
QHINT.dk_mole=T('You are a spy inside a dark faction. Someday the righteous will come for it.','你是潜伏在邪派里的卧底。总有一天，正道会来攻山。');

/* ====================== recruitment: life leads you to their door ====================== */
I({id:'dk_rc_villains',age:[16,60],cd:12,w:2,when:s=>dkFree(s)&&s.wanted>=2,ctx:s=>{const c=scene();c.npc=npc(s,{occ:26,sex:'m',age:rint(40,55),lv:PW(1.1,6)(s)});return c},
 text:()=>T('A fat man with a cleaver in his belt sits down at your table and eats your dinner without asking. "Li the Big Mouth, from the Valley of No Return," he says, chewing. "Half the constables in the province want you. In the Valley, nobody wants anybody. Come."','一个腰插菜刀的胖子在你桌边坐下，二话不说就吃起你的饭菜。"不归谷，李大嘴。"他边嚼边说，"半个省的捕快都在找你。到了谷里，谁也不找谁。来吧。"'),
 opts:[{l:T('Go to the Valley','去不归谷'),sub:T('Join the Valley of No Return. The constables stop at its mouth.','投奔不归谷。捕快追到谷口就止步了。'),out:[{t:T('The Valley is full of cheerful murderers. No constable has set foot in it for thirty years. You sleep well for the first time in months.','谷里尽是些笑嘻嘻的杀人犯。三十年来没有一个捕快踏进过这里。你几个月来第一次睡了个好觉。'),c:'bad',fx:{f:s=>{dkJoin('erengu')(s);s.wanted=0}}}]},
  {l:T('Decline','婉拒'),out:[{w:2,t:T('He finishes your wine as well and leaves you the bill.','他把你的酒也喝光了，账单留给了你。'),c:'muted',fx:{money:-5}},{w:1,t:T('"The offer stands," he says. "People like you always come in the end."','"话撂在这儿，"他说，"你这种人，最后都会来的。"'),c:'muted'}]},
  {l:T('Try to collect the bounty on him','拿他去换赏银'),fight:FG((s,c)=>c.npc.lv,'injury',T('Li the Big Mouth','李大嘴'),T('a cleaver from the Valley of No Return','不归谷的菜刀'),()=>T('Li the Big Mouth','李大嘴')),
   win:[{t:T('The magistrate pays 150 taels for him and quietly drops one of the warrants with your name on it.','县太爷为他付了一百五十两赏银，还悄悄撤了你的一张海捕文书。'),c:'good',fx:{money:150,wanted:-1,fame:3}}],
   lose:[{t:T('He looks at your arm the way a cook looks at a ham. You run.','他打量你胳膊的眼神，像厨子打量一只火腿。你跑了。'),c:'bad',fx:{happy:-3}}]}]});

I({id:'dk_rc_sunmoon',age:[16,55],cd:12,w:2,when:s=>dkFree(s)&&s.align<=-20,ctx:s=>{const c=scene();c.npc=npc(s,{occ:19,age:rint(50,65)});return c},
 text:c=>T(`An elder in purple from Soul-Severing Cliff, ${c.npc.en}, finds you at ${c.place.en}. "The righteous sects already call you a demon. Why not be paid for it?"`,`断魂崖来的紫袍长老${c.npc.zh}在${c.place.zh}找到了你。"名门正派早就骂你是魔头了。何不干脆领这份饷银？"`),
 opts:[{l:T('Kneel and chant the oath','跪下念誓词'),sub:T('Join the Crimson Sky Cult.','加入赤霄教。'),out:[{t:T('"May the Leader live a thousand autumns and unify the jianghu!" A red pill is pressed into your mouth. It tastes of iron and something that moves.','"教主千秋万载，一统江湖！"一颗红丸塞进了你嘴里。铁锈味，还有点什么在动。'),c:'bad',fx:{f:dkJoin('sunmoon')}}]},
  {l:T('Ask what the catch is','问有什么条件'),out:[{w:2,t:T('He shows you a red pill in a jade box and smiles. You decide you are busy.','他亮出玉盒里的一颗红丸，笑了笑。你决定自己很忙。'),c:'muted',fx:{smarts:1}},{w:1,t:T('"No catch," he says. There is always a catch. You leave before you find out which.','"没有条件。"他说。条件从来都有。你没等弄明白是什么就走了。'),c:'muted'}]},
  {l:T('Refuse','拒绝'),out:[{t:T('He leaves a black wooden token on the table. "When you change your mind."','他在桌上留下一块赤霄令牌。"等你回心转意。"'),c:'muted',fx:{align:2}}]}]});

I({id:'dk_rc_dragon',age:[18,55],cd:12,w:2.5,when:s=>dkFree(s)&&(s.job==='assassin'||(s.align<=-30&&power(s)>=45&&['jiangnan','capital','central'].includes(s.region))),
 text:()=>T('On the morning of your next job, a sheet of paper is waiting on your pillow. On it, a single green dragon in ink and a number: one hundred and twenty-seven. Branch 127 of the Night Owl Society needs a blade.','你下一单活的那天早上，枕头上多了一张纸。纸上只画了一条墨色青龙，旁边写着：一百二十七。夜枭会第一百二十七分坛缺一把刀。'),
 opts:[{l:T('Accept','接下'),sub:T('Join the Night Owl Society.','加入夜枭会。'),out:[{t:T('You never meet the man who recruited you. A purse appears, and orders, and a promise that you will never be lonely again, because someone will always be watching.','你始终没见过招你的人。只有一袋银子、一道命令，外加一个承诺：你再也不会孤单了，因为总会有人盯着你。'),c:'bad',fx:{money:100,f:dkJoin('qinglong')}}]},
  {l:T('Burn the paper','把纸烧了'),out:[{w:2,t:T('Next morning your client is dead and the fee is in your room anyway. A reminder that they know where you sleep.','第二天早上，你的雇主死了，酬金却照样出现在你房里。这是提醒：他们知道你睡在哪儿。'),c:'bad',fx:{money:50,happy:-4}},
   {w:1,t:T('Nothing happens. For a year you check under the bed every night.','什么事也没发生。整整一年，你每晚睡前都要看看床底下。'),c:'muted',fx:{happy:-3}}]}]});

I({id:'dk_rc_seasand',age:[16,55],cd:12,w:2.5,when:s=>dkFree(s)&&(s.job==='smuggler'||(s.region==='east'&&s.align<=-10)),ctx:s=>{const c=scene();c.npc=npc(s,{occ:16,sex:'m',age:rint(35,50)});return c},
 text:c=>T(`A one-eared boatman, ${c.npc.en}, leans on your salt barrels. "The Black Tide Gang owns this coast. You run salt on it. So you either run it for us, or you swim."`,`独耳船老大${c.npc.zh}靠在你的盐桶上。"这片海是黑潮帮的。你在这儿贩私盐，要么替我们贩，要么下海喂鱼。"`),
 opts:[{l:T('Run salt for the gang','替黑潮帮贩盐'),sub:T('Join the Black Tide Gang.','加入黑潮帮。'),out:[{t:T('They give you a boat with no name and a knife with a long one. The tides are yours now.','他们给了你一条没名字的船，和一把名头很响的刀。从此潮水归你管。'),c:'bad',fx:{f:dkJoin('haisha')}}]},
  {l:T('Refuse','不干'),out:[{w:2,t:T('That night your boat burns down to the waterline.','当晚，你的船烧得只剩个底。'),c:'bad',fx:{money:-40,happy:-4}},{w:1,t:T('He laughs, spits in the sea and lets you be. Someone above him must owe you a favour.','他大笑，往海里啐了一口，放过了你。大概他上头有人欠你人情。'),c:'muted'}]}]});

I({id:'dk_rc_money',age:[18,60],cd:12,w:2.5,when:s=>dkFree(s)&&(s.job==='enforcer'||(s.money>=600&&s.align<=5)),
 text:()=>T('A man in a golden robe sets a gold ring on your table. "Chief Shangguan of the Coin Gang says everything has a price. He wishes to know yours."','一个金袍人把一枚金环放在你桌上。"通宝帮上官帮主说，天下万物皆有价。他想知道你的价钱。"'),
 opts:[{l:T('Name a price','开个价'),sub:T('Join the Coin Gang.','加入通宝帮。'),out:[{t:T('He pays it without blinking, which tells you it was too low. You are a member of the Coin Gang.','他眼都没眨就付了。这说明你开低了。你成了通宝帮的人。'),c:'bad',fx:{money:200,f:dkJoin('jinqian')}}]},
  {l:T('"I am not for sale."','"我不卖。"'),out:[{w:2,t:T('"Everyone says that," he says, "until the price is right." He leaves the ring.','"人人都这么说，"他道，"直到价钱合适为止。"金环他留下了。'),c:'muted',fx:{money:20,align:2}},{w:1,t:T('Your landlord raises your rent the next day. And the day after. The Coin Gang owns the street.','第二天房东就涨了租，第三天又涨。这条街是通宝帮的。'),c:'bad',fx:{money:-60}}]}]});

I({id:'dk_rc_ruined',age:[20,60],cd:15,w:2.5,when:s=>dkFree(s)&&s.money<10&&s.happy<45,ctx:s=>{const c=scene();c.npc=npc(s,{occ:22,age:rint(20,35)});return c},
 text:c=>T(`You are sleeping in ${c.place.en} with nothing left when ${c.npc.en}, a disciple of the Seven Fiends Sect, beats a gong over your head. "Rice and a roof for anyone who sings the praises of the Old Immortal! His virtue outshines the sun and the moon!"`,`你身无分文，正睡在${c.place.zh}，七煞门弟子${c.npc.zh}在你头顶咣地敲了一声锣。"凡肯歌颂七煞老祖者，管吃管住！老仙德配天地，威震寰宇！"`),
 opts:[{l:T('Sing','唱'),sub:T('Join the Seven Fiends Sect.','加入七煞门。'),out:[{t:T('You sing louder than anyone. They feed you. Somewhere a small part of you dies, but it was not a part that ate.','你唱得比谁都响。他们管了饭。你心里有一小块东西死掉了，不过那块不管吃饭。'),c:'bad',fx:{happy:4,f:dkJoin('xingxiu')}}]},
  {l:T('Ask for food only','只讨口吃的'),out:[{w:2,t:T('They give you a bun. Your stomach cramps all night. The Seven Fiends does not give anything for free.','他们给了你一个馒头。你肚子疼了一整夜。七煞门从不白给。'),c:'bad',fx:{hurt:[3,8],cause:T('a Seven Fiends bun','七煞门的馒头')}},{w:1,t:T('The disciple is new and still kind. He shares his own dinner and asks you not to tell.','这弟子刚入门，心还软。他把自己的晚饭分给你，叫你别说出去。'),c:'good',fx:{heal:5,happy:2}}]},
  {l:T('Tell him to stop banging the gong','叫他别敲了'),out:[{t:T('He bangs it harder, singing about the Old Immortal’s magnificent eyebrows.','他敲得更响了，还唱起老仙那两道英明神武的眉毛。'),c:'muted',fx:{happy:-1}}]}]});

I({id:'dk_rc_cultblood',age:[14,40],once:1,w:3,when:s=>dkFree(s)&&(s.family==='cult'||s.seen.cultkid!=null),ctx:s=>{const c=scene();c.npc=npc(s,{occ:18,age:rint(60,75)});return c},
 text:c=>T(`An old woman you have never met, ${c.npc.en}, calls you by your milk name. "Your mother swore you to the Holy Cult before you were born. Soul-Severing Cliff has been patient."`,`一个从没见过的老婆婆${c.npc.zh}叫出了你的乳名。"你娘还没生你，就把你许给了赤霄教。断魂崖等你很久了。"`),
 opts:[{l:T('Go to Soul-Severing Cliff','上断魂崖'),sub:T('Join the Crimson Sky Cult.','加入赤霄教。'),out:[{t:T('They greet you like a lost child. Then they give you the pill, like a found one.','他们像迎接走失的孩子一样迎接你。然后把药丸递给你，像对待找回来的孩子那样。'),c:'bad',fx:{f:dkJoin('sunmoon')}}]},
  {l:T('Refuse, gently','好言回绝'),out:[{t:T('She cries a little and gives you your mother’s silver hairpin. "She would have wanted you to choose."','她哭了一会儿，把你娘的银簪子塞给你。"她也会愿意让你自己选。"'),c:'good',fx:{happy:3,align:3}}]},
  {l:T('Tell her the cult can rot','叫她滚，赤霄教去死'),out:[{t:T('She stops crying at once. "Then your mother’s oath is broken, and oaths have a cost." Your shoulder aches for a year.','她立刻不哭了。"那你娘的誓就破了，破誓是要还的。"你的肩膀疼了一整年。'),c:'bad',fx:{hurt:[5,12],cause:T('a cult grandmother’s needle','赤霄教老婆婆的毒针'),align:4}}]}]});

I({id:'dk_rc_venom',age:[14,45],cd:15,w:2.5,when:s=>dkFree(s)&&['miao','shu'].includes(s.region)&&s.align<=15,ctx:s=>{const c=scene();c.npc=npc(s,{occ:29,sex:'f',age:rint(20,30)});return c},
 text:c=>T(`A green snake bites you on a mountain path. A Miao girl in silver bells, ${c.npc.en}, sucks out the venom and spits it in the ferns. "The Five Venoms Sect never saves anyone for free," she says.`,`山路上一条青蛇咬了你一口。一个戴着银铃的苗家姑娘${c.npc.zh}替你吸出毒血，吐在蕨丛里。"五毒教救人，从不白救。"她说。`),
 opts:[{l:T('Pay her with yourself','以身相报——入教'),sub:T('Join the Five Venoms Sect.','加入五毒教。'),out:[{t:T('She laughs at your choice of words and takes you to a village of scorpions and singing.','她被你的说法逗笑了，带你去了一个满是蝎子和山歌的寨子。'),c:'bad',fx:{f:dkJoin('wudu'),meet:'friend',bond:55}}]},
  {l:T('Pay in silver','给银子'),cost:30,out:[{t:T('She weighs the silver, bites a coin and wishes you a long life. You choose to take this kindly.','她掂了掂银子，咬了咬铜钱，祝你长命百岁。你决定往好处想。'),c:'muted'}]},
  {l:T('Thank her and walk on','道谢走人'),out:[{t:T('"Suit yourself." The fever comes three days later. She left some venom in, just a little.','"随你。"三天后你发起了高烧。她留了一点毒在里面，就一点。'),c:'bad',fx:{ill:'fever',hurt:[4,10],cause:T('a snake bite','蛇毒')}}]}]});

I({id:'dk_rc_bloodsaber',age:[16,50],cd:15,w:2.5,when:s=>dkFree(s)&&s.align<=-25&&power(s)>=25&&['north','west'].includes(s.region),ctx:s=>{const c=scene();c.npc=npc(s,{occ:22,age:rint(30,50),lv:PW(1.05,6)(s)});return c},
 text:c=>T(`A red-robed monk, ${c.npc.en}, has been watching you fight. He licks his lips. "You enjoy it. Don’t pretend. The Ancestor of the Red Blade Sect would like you very much."`,`一个红袍番僧${c.npc.zh}一直在旁看你动手。他舔了舔嘴唇。"你喜欢杀人，别装了。赤刃老祖一定很喜欢你。"`),
 opts:[{l:T('Follow him to the snow','随他上雪山'),sub:T('Join the Red Blade Sect.','加入赤刃门。'),out:[{t:T('On the plateau they give you a thin saber that drinks the light. They call you brother. You do not ask what happened to the last one.','高原上，他们给了你一柄吸光的薄刀，管你叫师兄弟。你没问上一个用这把刀的人去了哪儿。'),c:'bad',fx:{f:dkJoin('xuedao')}}]},
  {l:T('"I am nothing like you."','"我和你们不一样。"'),fight:FG((s,c)=>c.npc.lv,'injury',T('The red monk','红袍番僧'),T('a Red Blade monk','赤刃僧')),
   win:[{t:T('He goes down laughing. "See? You do enjoy it."','他倒下时还在笑。"瞧，你就是喜欢。"'),c:'muted',fx:{fame:3,align:2}}],
   lose:[{t:T('He nicks your cheek and walks off humming. The scar itches whenever you are angry.','他在你脸上划了一道，哼着曲子走了。每当你发怒，这道疤就发痒。'),c:'bad',fx:{looks:-3}}]}]});

/* ====================== dark-faction daily life (chore) ====================== */
const DKC=['chore'];
I({id:'dk_ch_protect',age:[12,80],cd:4,w:1.2,tags:DKC,when:dkEv,ctx:s=>{const c=scene();c.npc=npc(s,{occ:27,age:rint(35,55)});return c},
 text:c=>T(`You are sent to collect this month’s protection money. ${c.npc.en}, a widow with a noodle stall, has only half of it.`,`你奉命去收这个月的保护费。摆面摊的寡妇${c.npc.zh}只凑得出一半。`),
 opts:[{l:T('Squeeze her','逼她交'),out:[{w:3,t:T('She hands over her savings and the cooking pot. You carry both back.','她交出了积蓄，连锅都给了你。你两样都扛了回去。'),c:'bad',fx:{money:15,merit:4,align:-4}},{w:1,t:T('Her son hits you with a rolling pin. You still take the money. You are less proud of it than of the rolling pin.','她儿子拿擀面杖敲了你一下。钱你照收，可你心里更佩服那根擀面杖。'),c:'muted',fx:{merit:3,align:-3,hurt:[2,6],cause:T('a rolling pin','擀面杖')}}]},
  {l:T('Make up the rest yourself','差的你自己补'),cost:20,out:[{t:T('The hall master is satisfied. The widow feeds you noodles free for a year and never asks why.','堂主满意了。寡妇白请你吃了一年的面，从没问过为什么。'),c:'good',fx:{merit:4,align:4,happy:3}}]},
  {l:T('Let it slide','算了'),out:[{w:2,t:T('The hall master docks your share and calls you soft in front of everyone.','堂主扣了你的份子，当众骂你心软。'),c:'muted',fx:{merit:-3,align:2}},{w:1,t:T('Nobody checks the ledger this month. Lucky.','这个月没人查账。运气好。'),c:'good',fx:{align:2}}]}]});

I({id:'dk_ch_poison',age:[12,80],cd:5,tags:DKC,when:dkEv,
 text:(c,s)=>T('The poison hall has a new brew and needs someone to test it.','毒堂新炼了一味毒，要人试药。'),
 opts:[{l:T('Test it on yourself','自己试'),out:[{w:s=>s.t.root,t:T('You sweat black for a night and wake up stronger. Your body remembers the poison and will refuse it next time.','你出了一夜的黑汗，醒来反倒更强了。身子记住了这毒，下回就不怕了。'),c:'good',fx:{qi:5,maxHealth:2,merit:4}},{w:4,t:T('You lie on the floor for a week, talking to your dead grandmother.','你在地上躺了七天，一直和死去的祖母说话。'),c:'bad',fx:{hurt:[8,20],cause:T('testing a poison','试毒'),merit:5}}]},
  {l:T('Test it on a prisoner','拿囚犯试'),out:[{t:T('The notes are very precise. You do not sleep well, but the notes are very precise.','记录写得很精确。你睡不好觉，但记录写得很精确。'),c:'bad',fx:{align:-6,merit:5,happy:-3}}]},
  {l:T('Swap it for sugar water and lie','换成糖水，编个结果'),out:[{w:s=>s.smarts/20,t:T('You write up the symptoms so well the poison master praises his own brew.','你把症状编得活灵活现，毒堂主对着自己的方子大加赞赏。'),c:'good',fx:{align:3,merit:3,smarts:1}},{w:2,t:T('The poison master drinks a sip to prove a point. Nothing happens. He looks at you for a long time.','毒堂主为了证明药性，亲自抿了一口。什么事也没有。他盯着你看了很久。'),c:'bad',fx:{align:3,merit:-3,flag:'dk_suspect'}}]}]});

I({id:'dk_ch_halls',age:[14,80],cd:6,tags:DKC,when:dkEv,ctx:s=>{const c=scene();c.a=npc(s,{age:rint(40,60)});c.b=npc(s,{age:rint(30,45)});return c},
 text:(c,s)=>T(`Two hall masters are at war inside ${dkS(s).en}: old ${c.a.en} of the Left Hall and young ${c.b.en} of the Right Hall. Both want your sword.`,`${dkS(s).zh}里两位堂主斗得不可开交：左堂的老${c.a.zh}，右堂的少壮${c.b.zh}。两边都想拉你入伙。`),
 opts:[{l:c=>T(`Back old ${c.a.en}`,`投靠老${c.a.zh}`),out:[{w:1,t:c=>T(`${c.a.en} wins. You are rewarded with ${c.b.en}’s office and his very nice chair.`,`${c.a.zh}赢了。你分到了${c.b.zh}的屋子，还有他那把很舒服的椅子。`),c:'good',fx:{merit:8,money:30}},{w:1,t:c=>T(`${c.b.en} wins. Old ${c.a.en} is found floating in the pond, and you spend a month cleaning latrines.`,`${c.b.zh}赢了。老${c.a.zh}被人发现漂在池塘里，你被罚去扫了一个月茅房。`),c:'bad',fx:{merit:-4,happy:-4}}]},
  {l:c=>T(`Back young ${c.b.en}`,`投靠少壮的${c.b.zh}`),out:[{w:1,t:c=>T(`${c.b.en} wins. You get a fine new title and a great many enemies.`,`${c.b.zh}赢了。你得了个好听的新头衔，还有一大堆仇人。`),c:'good',fx:{merit:8,meet:'enemy',bond:5}},{w:1,t:c=>T(`${c.b.en} loses and flees in the night. You are flogged for his ambitions.`,`${c.b.zh}败了，连夜出逃。你替他的野心挨了一顿鞭子。`),c:'bad',fx:{merit:-4,hurt:[6,14],cause:T('a flogging','鞭刑'),soft:1}}]},
  {l:T('Smile at both','两边都赔笑'),out:[{w:s=>s.smarts/25,t:T('Both think you are secretly theirs. Both pay you. You learn how the jianghu really works.','两边都以为你暗地里是自己人，两边都给你银子。你明白了江湖到底是怎么回事。'),c:'gold',fx:{money:60,smarts:3,merit:2}},{w:2,t:T('Both find out. For a while you eat alone.','两边都发现了。有好一阵子，你只能一个人吃饭。'),c:'muted',fx:{happy:-4}}]}]});

I({id:'dk_ch_paranoia',age:[14,80],cd:6,tags:DKC,when:dkEv,
 text:(c,s)=>T(`${dkL(s).en} is sure there is a traitor in the ranks. Everyone at the assembly must name one.`,`${dkL(s).zh}认定教中出了叛徒。大会上每个人都得指认一个。`),
 opts:[{l:T('Name a rival','指认一个对头'),out:[{t:T('Your rival is dragged off screaming. Nobody sits near you at dinner, and you get his rice ration.','你的对头被拖走了，一路惨叫。晚饭时没人敢坐你旁边，他那份米归了你。'),c:'bad',fx:{align:-5,merit:5,enemy:1}}]},
  {l:T('Name nobody','谁也不指认'),out:[{w:1,t:T('The lord stares at you, then laughs. "At least one of you has a spine." He moves on.','教主盯着你，忽然笑了。"总算有个有骨头的。"他没再追究。'),c:'good',fx:{merit:3,align:3}},{w:2,t:T('Twenty lashes for "lack of zeal".','以"不够忠心"论处，抽了二十鞭。'),c:'bad',fx:{hurt:[8,16],cause:T('a flogging','鞭刑'),soft:1,align:3}}]},
  {l:T('Confess to stealing a chicken','坦白自己偷过一只鸡'),out:[{w:1,t:T('The hall goes silent, then roars with laughter. The purge ends early. Several people buy you wine.','满堂一静，接着哄堂大笑。清洗提前结束了。好几个人请你喝酒。'),c:'good',fx:{happy:4,merit:2}},{w:1,t:T('The lord does not laugh. You are made to eat a raw chicken, feathers and all.','教主没笑。你被逼着生吞了一只鸡，连毛带骨。'),c:'bad',fx:{hurt:[3,8],cause:T('a raw chicken','生吞活鸡'),happy:-4}}]}]});

I({id:'dk_ch_rival',age:[14,80],cd:5,tags:DKC,when:dkEv,ctx:s=>{const c=scene();c.rk=dkRivalK(s);c.npc=npc(s,{age:rint(25,45),lv:PW(.95,4)(s)});return c},
 text:c=>T(`At ${c.place.en}, men of ${dkST(c.rk).en} are collecting from stalls that pay your faction. Their leader, ${c.npc.en}, grins at you.`,`${c.place.zh}，${dkST(c.rk).zh}的人在收本该交给你们的份子钱。领头的${c.npc.zh}冲你咧嘴一笑。`),
 opts:[{l:T('Drive them off','赶走他们'),fight:FG((s,c)=>c.npc.lv,'injury',T('Turf war','争地盘'),T('a turf war between dark factions','邪派争地盘')),
   win:[{t:T('They leave their bags of copper behind. The stall-keepers bow to you, which is not the same as liking you.','他们连钱袋都扔下了。摊主们向你鞠躬，那不等于喜欢你。'),c:'good',fx:{merit:6,money:25,fame:2}}],
   lose:[{t:T('You limp home. The hall master says losing to them is worse than losing the money.','你一瘸一拐地回来了。堂主说，输给他们比丢了钱还丢人。'),c:'bad',fx:{merit:-2}}]},
  {l:T('Negotiate a split','谈判分账'),out:[{w:s=>s.smarts/20,t:T('Odd days theirs, even days yours. Both factions call it a victory.','单日归他们，双日归你们。两边都说自己赢了。'),c:'good',fx:{merit:4,smarts:2}},{w:2,t:T('Talks break down over who pays for the tea. Blood is spilled, mostly tea.','谈判在谁付茶钱上崩了。洒了一地的，主要是茶。'),c:'muted',fx:{merit:1}}]}]});

I({id:'dk_ch_prisoner',age:[12,80],cd:5,w:1.2,tags:DKC,when:dkEv,ctx:s=>{const c=scene();c.rk=dkRightK();c.npc=npc(s,{age:rint(16,24)});return c},
 text:c=>T(`You guard the cellar tonight. The prisoner is ${c.npc.en}, a young disciple of ${dkST(c.rk).en}, barely more than a child. ${c.npc.He} has not eaten in four days.`,`今夜你看守地牢。囚犯是${dkST(c.rk).zh}的年轻弟子${c.npc.zh}，还是个半大孩子，已经四天没吃东西了。`),
 opts:[{l:T('Torment the prisoner for secrets','拷问口供'),out:[{w:1,t:T('The prisoner breaks and talks. The hall master is pleased. You wash your hands for a long time.','囚犯熬不住，招了。堂主很满意。你洗了很久的手。'),c:'bad',fx:{align:-6,merit:6,happy:-3}},{w:1,t:T('The prisoner spits in your face and says nothing. You gain nothing, and lose something.','囚犯啐了你一脸，一个字没说。你一无所得，却丢了点什么。'),c:'bad',fx:{align:-5,merit:2}}]},
  {l:T('Secretly free the prisoner','偷偷放人'),sub:T('Alignment up. Someone may notice.','正气大增，但可能被发现。'),out:[{w:2,t:T('The lock is found picked in the morning. A guard on another shift is blamed. You do not sleep well, for different reasons.','早上发现锁被撬了，罪名落到另一班看守头上。你睡不好，但原因不一样了。'),c:'good',fx:{align:8,merit:-1}},{w:1,t:T('The Punishment Hall asks who held the keys last night.','刑堂开始追问昨夜钥匙在谁手上。'),c:'bad',fx:{align:8,merit:-3,flag:'dk_suspect'}},{w:1,t:c=>T(`Months later a letter arrives with no name: "I remember you." It is from ${c.npc.en}.`,`几个月后，来了一封没署名的信："我记得你。"是${c.npc.zh}写的。`),c:'good',fx:{align:8,meet:'friend',bond:70}}]},
  {l:T('Share your own food','把自己的饭分给他'),out:[{t:T('You eat half rations for a week and say nothing. So does the prisoner.','你吃了一个星期的半份饭，一声不吭。囚犯也一声不吭。'),c:'muted',fx:{align:3,happy:1}}]}]});

I({id:'dk_ch_pill',age:[10,90],cd:2,w:1.8,tags:DKC,when:s=>s.sect==='sunmoon',
 text:()=>T('It is the Dragon Boat Festival, when the Leader hands out the antidote to the Heart-Eating Pill. Without it the corpse-worms wake and eat their way to your brain. Everyone kneels in a long line.','端午到了，教主要分发噬心丹的解药。没有解药，尸虫苏醒，会一路啃进脑子里。人人跪成长长一排。'),
 opts:[{l:T('Kneel and praise the Leader','跪下颂圣'),out:[{w:3,t:T('"The Leader is wise and holy!" You get your pill. You also get a sore throat.','"教主圣明，泽被苍生！"你领到了解药，还喊哑了嗓子。'),c:'muted',fx:{merit:2}},{w:1,t:T('The Leader dislikes your tone and gives you half a dose. All year your head buzzes like a beehive.','教主嫌你语气不对，只给了半颗。一整年你脑袋里都像有个蜂窝在嗡嗡响。'),c:'bad',fx:{hurt:[6,14],cause:T('the corpse-worms','噬心蛊'),soft:1,smarts:-2}}]},
  {l:T('Bribe the steward for a spare dose','贿赂管事多要一颗'),cost:60,out:[{w:2,t:T('He slips you a second pill. You sew it into your collar, for the day you leave.','他偷偷多塞给你一颗。你把它缝进衣领里，留着离开的那天用。'),c:'good',fx:{flag:'dk_spare'}},{w:1,t:T('He takes the silver and reports you. Twenty lashes and a lecture on gratitude.','他收了银子，转头就告了你。二十鞭，外加一通"知恩图报"的训话。'),c:'bad',fx:{hurt:[6,12],cause:T('a flogging','鞭刑'),soft:1,merit:-3}}]},
  {l:T('Study the pill instead of swallowing at once','先研究解药，不急着吞'),if:s=>s.smarts>=55,out:[{w:1,t:T('You work out half the recipe before the worms start to stir. Half is not enough, but it is a start.','尸虫开始躁动之前，你推出了一半的方子。一半不够，但总是个开头。'),c:'gold',fx:{smarts:4,flag:'dk_recipe'}},{w:2,t:T('You learn nothing, except that the worms do not like waiting.','你什么也没弄明白，只知道尸虫不爱等。'),c:'bad',fx:{hurt:[4,10],cause:T('the corpse-worms','噬心蛊'),soft:1}}]}]});

I({id:'dk_ch_flattery',age:[10,80],cd:3,w:1.6,tags:DKC,when:s=>s.sect==='xingxiu',
 text:()=>T('The Old Immortal has returned to the lodge. The disciples compete to praise him; the loudest is promoted, the quietest is used for poison practice.','七煞老祖回山了。弟子们争相颂扬，嗓门最大的升职，最小的拿去试毒。'),
 opts:[{l:T('Compose a new ode','新作一首颂诗'),out:[{w:s=>s.smarts/15,t:T('"His wisdom is so vast the sea asks him for advice." He weeps with joy and makes you a herald.','"老仙智慧浩瀚，连大海都要向他请教。"老仙喜极而泣，封你做了传令弟子。'),c:'gold',fx:{merit:8,smarts:2}},{w:2,t:T('Your ode is too subtle. Nobody understands it. A junior with a gong out-shouts you.','你的颂诗太含蓄，没人听得懂。一个敲锣的小师弟把你压了下去。'),c:'muted',fx:{merit:1}}]},
  {l:T('Bang the gong loudest','把锣敲得最响'),out:[{t:T('Your ears ring for a week. The Old Immortal nods at you once. It is enough.','你耳朵嗡嗡响了一个星期。老仙冲你点了一下头。够了。'),c:'good',fx:{merit:4,happy:-1}}]},
  {l:T('Keep your dignity','保住自己的体面'),out:[{w:2,t:T('A junior points at you: "That one is not singing!" You spend a week as a poison dummy.','一个小师弟指着你喊："那个人没唱！"你被拿去当了一个星期的毒靶子。'),c:'bad',fx:{hurt:[6,14],cause:T('corpse poison practice','尸毒练功'),align:2}},{w:1,t:T('Nobody notices you in the din. Dignity, it turns out, is mostly about being quiet in a loud room.','锣鼓喧天，没人注意到你。原来体面，多半就是在吵闹的屋子里安静一点。'),c:'muted',fx:{align:2,happy:1}}]}]});

I({id:'dk_ch_defect',age:[14,70],cd:8,tags:DKC,when:dkEv,ctx:s=>{const c=scene();c.npc=npc(s,{age:s.age+rint(-5,5)});return c},
 text:c=>T(`${c.npc.en}, who swore brotherhood with you over a bowl of blood wine, whispers that ${c.npc.he} is fleeing tonight. "Come with me."`,`当初与你歃血为盟的${c.npc.zh}悄悄说，${c.npc.ta}今晚就要逃。"跟我一起走。"`),
 opts:[{l:T('Report it','告发'),out:[{t:c=>T(`${c.npc.en} is caught at the gate. ${c.npc.He} looks at you once as they drag ${c.npc.him} away. You are rewarded.`,`${c.npc.zh}在山门被抓住了。被拖走时，${c.npc.ta}只看了你一眼。你得了赏。`),c:'bad',fx:{merit:8,align:-6,happy:-4,money:40}}]},
  {l:T('Go together','一起走'),sub:T('You will be a deserter.','你将成为叛徒。'),out:[{w:2,t:T('You go over the wall before the moon rises. By dawn you are free, and hunted.','月亮升起前你们翻过了墙。天亮时你自由了，也被追杀了。'),c:'gold',fx:{align:6,meet:'sworn',bond:80,f:s=>{if(s.sect)leaveSect(s)}}},{w:1,t:T('The dogs find you in the ravine. You escape; your brother does not.','猎犬在山沟里找到了你们。你逃掉了，兄弟没有。'),c:'bad',fx:{align:4,hurt:[10,22],cause:T('the faction’s hounds','追兵的猎犬'),happy:-8,f:s=>{if(s.sect)leaveSect(s)}}}]},
  {l:T('Say nothing, and give silver','不声张，塞些盘缠'),cost:20,out:[{w:2,t:T('Your brother vanishes. A year later a jar of good wine arrives with no note.','兄弟不见了。一年后有人送来一坛好酒，没留字条。'),c:'good',fx:{align:4,happy:3}},{w:1,t:T('Your brother is caught, and under the knife, names you.','兄弟被抓了。在刀下，把你供了出来。'),c:'bad',fx:{align:3,flag:'dk_suspect'}}]}]});

I({id:'dk_ch_loyalty',age:[14,80],cd:8,tags:DKC,when:dkEv,ctx:s=>{const c=scene();c.npc=npc(s,{occ:19,age:rint(60,75)});return c},
 text:c=>T(`A loyalty test. ${c.npc.en}, a village elder who refused to pay tribute, kneels in front of you. You are handed a saber. The hall watches.`,`忠心考验。不肯交供奉的村老${c.npc.zh}跪在你面前。有人塞给你一把刀。满堂的人都看着你。`),
 opts:[{l:T('Do it','动手'),out:[{t:T('The hall cheers. You are one of them now, and it shows in your eyes.','满堂喝彩。你如今算是自己人了，眼神里看得出来。'),c:'bad',fx:{align:-10,merit:8,happy:-6}}]},
  {l:T('Fake it','做个假'),out:[{w:s=>s.t.wit,t:T('A quick cut, a bag of pig’s blood under his collar, and a body dumped in the river that swims away at night. Nobody checks.','一刀下去，衣领里藏的猪血袋破了。"尸首"扔进河里，夜里自己游走了。没人去查。'),c:'gold',fx:{align:6,merit:6}},{w:3,t:T('The pig’s blood smells like pig. The Punishment Hall is very interested.','猪血一股猪味儿。刑堂对此很感兴趣。'),c:'bad',fx:{align:6,merit:-2,flag:'dk_suspect'}}]},
  {l:T('Refuse openly','当众拒绝'),out:[{t:T('Thirty lashes. The old man is spared, for now, because the hall master is busy with you.','三十鞭。老人暂时逃过一劫，因为堂主忙着收拾你。'),c:'bad',fx:{align:6,merit:-6,hurt:[10,20],cause:T('a flogging','鞭刑'),soft:1}}]}]});

I({id:'dk_ch_villains',age:[14,80],cd:3,w:1.5,tags:DKC,when:s=>s.sect==='erengu',
 text:()=>T('Xuanyuan Sanguang, the Villain who bets on anything, puts two flies under a bowl. "Which one leaves first? I’ll take your left hand against two hundred taels."','谷中十凶里什么都赌的轩辕三光把两只苍蝇扣在碗下。"哪只先飞出来？我拿二百两赌你一只左手。"'),
 opts:[{l:T('Bet your left hand','押上左手'),out:[{w:s=>s.t.luck,t:T('Your fly leaves first. He pays at once and calls you his little brother for a month.','你那只苍蝇先飞了。他当场付钱，还叫了你一个月的小兄弟。'),c:'gold',fx:{money:200,fame:2,merit:2}},{w:4,t:T('You lose. He looks at your hand, then laughs. "Keep it. I only wanted to see your face." Your face, it seems, was worth it.','你输了。他看了看你的手，大笑："留着吧，我就想看看你那副脸。"看来你那副脸确实值这个价。'),c:'muted',fx:{happy:-3}}]},
  {l:T('Bet twenty taels instead','只押二十两'),cost:20,out:[{w:1,t:T('You win forty. He calls you boring and sulks all day.','你赢了四十两。他骂你没意思，生了一天闷气。'),c:'good',fx:{money:40}},{w:1,t:T('You lose. "Harm others, benefit yourself!" shouts Bai Kaixin from the roof, though it has nothing to do with him.','你输了。"损人利己！"白开心在房顶上喊，虽然这事跟他半点关系没有。'),c:'muted'}]},
  {l:T('Refuse','不赌'),out:[{t:T('"I bet you’d refuse," he says, and collects from three villains who bet otherwise.','"我就赌你不敢。"他说着，从三个押你敢的恶人手里收了钱。'),c:'muted',fx:{happy:2}}]}]});

I({id:'dk_ch_money',age:[14,80],cd:3,w:1.5,tags:DKC,when:s=>s.sect==='jinqian',ctx:s=>{const c=scene();c.npc=npc(s,{occ:1,age:rint(30,50)});return c},
 text:c=>T(`Chief Shangguan’s ledger says ${c.npc.en}, a ruined scholar, owes the Coin Gang three hundred taels. He owns a brush, an inkstone and a daughter.`,`上官帮主的账本上写着，落魄书生${c.npc.zh}欠通宝帮三百两。他只有一支笔、一方砚，和一个女儿。`),
 opts:[{l:T('Collect with your fists','用拳头收'),out:[{t:T('He pays in copper and teeth. You keep a tenth, as is the custom.','他拿铜板和牙来还。照规矩，你抽一成。'),c:'bad',fx:{money:30,merit:5,align:-5}}]},
  {l:T('Take his calligraphy instead','拿他的字画抵账'),out:[{w:1,t:T('A collector pays five hundred for one scroll. The chief is amused and promotes your judgement, if not you.','一位藏家出五百两买走了其中一幅。帮主乐了，夸你眼光好，虽然没给你升职。'),c:'gold',fx:{money:60,merit:6,smarts:2}},{w:2,t:T('His calligraphy is terrible. The debt stays on the books, and so does your name next to it.','他的字写得奇丑。账还挂着，你的名字也挂在旁边。'),c:'muted',fx:{merit:-2,smarts:1}}]},
  {l:T('Forge the ledger','改账本'),out:[{w:s=>s.smarts/20,t:T('A careful brush, a slipped decimal, and the debt was always thirty. The scholar never learns why.','小心落笔，挪了一位数，那笔账原本就只有三十两。书生始终不知道为什么。'),c:'good',fx:{align:6,merit:-1}},{w:2,t:T('The Coin Gang has accountants who check the accountants.','通宝帮的账房，还有专查账房的账房。'),c:'bad',fx:{align:5,flag:'dk_suspect'}}]}]});

I({id:'dk_ch_salt',age:[14,75],cd:3,w:1.5,tags:DKC,when:s=>s.sect==='haisha',ctx:s=>{const c=scene();c.npc=npc(s,{occ:9,age:rint(30,50),lv:PW(.95,4)(s)});return c},
 text:c=>T(`A night salt run along the coast. A navy patrol boat comes out of the fog with a lantern and Captain ${c.npc.en} on the bow.`,`夜里沿海贩盐。一艘水师巡船从雾里钻出来，船头挑着灯笼，站着${c.npc.zh}把总。`),
 opts:[{l:T('Fight them off','打退巡船'),fight:FG((s,c)=>c.npc.lv,'injury',T('Salt run at night','夜贩私盐'),T('a navy patrol','水师巡船')),
   win:[{t:T('The patrol boat drifts away with a broken mast. The salt arrives. So does a warrant.','巡船断了桅杆，漂走了。盐送到了，海捕文书也到了。'),c:'good',fx:{merit:7,money:40,wanted:1}}],
   lose:[{t:T('You go over the side and swim for it. The salt goes to the captain’s cousin.','你翻下船游走了。那船盐归了把总的表弟。'),c:'bad',fx:{merit:-2}}]},
  {l:T('Bribe the captain','塞钱给把总'),cost:40,out:[{t:T('The captain looks at the moon for a while. When he looks back, you are gone.','把总抬头看了一会儿月亮。等他低下头，你已经不见了。'),c:'good',fx:{merit:4}}]},
  {l:T('Dump the salt overboard','把盐倒进海里'),out:[{t:T('The sea gets saltier. The gang takes it out of your pay.','海更咸了。帮里从你的份子里扣了这笔。'),c:'muted',fx:{merit:-3,money:-20}}]}]});

I({id:'dk_ch_xuedao',age:[14,75],cd:4,w:1.5,tags:DKC,when:s=>s.sect==='xuedao',
 text:()=>T('The Red Blade Ancestor sends you down to the plains to "find a wife" for the hall master. He does not mean a matchmaker.','赤刃老祖打发你下山，给堂主"找个老婆"。他说的可不是请媒婆。'),
 opts:[{l:T('Snatch a girl from a village','去村里抢人'),out:[{t:T('You ride back up the mountain with a screaming bundle over your saddle. The Ancestor laughs for a whole minute.','你骑马回山，鞍上横着一个哭喊的包袱。老祖笑了足有一盏茶的工夫。'),c:'bad',fx:{align:-10,merit:7,wanted:1}}]},
  {l:T('Hire a real matchmaker','真去请个媒婆'),out:[{w:2,t:T('You bring back a stout widow who wanted adventure. She beats the hall master in their first argument. He is delighted.','你带回一个想见世面的壮实寡妇。头一回吵架她就把堂主揍了。堂主乐坏了。'),c:'good',fx:{merit:4,happy:5,align:3}},{w:1,t:T('The matchmaker takes one look at the hall master and walks back down the mountain. You are blamed.','媒婆看了堂主一眼，转身下山了。锅是你背的。'),c:'muted',fx:{merit:-2,hurt:[3,8],cause:T('the hall master’s temper','堂主的脾气'),soft:1}}]},
  {l:T('Get lost in a snowstorm on purpose','故意在暴风雪里迷路'),out:[{t:T('You come back three weeks later with frostbitten toes and a story. Nobody believes it, but nobody can prove otherwise.','三个星期后你回来了，冻坏了脚趾，带回一个故事。没人信，也没人能拆穿。'),c:'muted',fx:{align:4,hurt:[4,10],cause:T('frostbite','冻伤'),soft:1}}]}]});

I({id:'dk_ch_qinglong',age:[16,80],cd:4,w:1.5,tags:DKC,when:s=>s.sect==='qinglong',ctx:s=>{const c=scene();c.npc=npc(s,{occ:17,age:rint(40,60)});return c},
 text:c=>T(`An order arrives: a single green dragon in ink and a day number. Kill ${c.npc.en}, who sells roast chestnuts on your corner. You have bought chestnuts from ${c.npc.him} for two years.`,`命令到了：一条墨龙，一个日子。杀了街角卖糖炒栗子的${c.npc.zh}。你在${c.npc.ta}那儿买了两年栗子。`),
 opts:[{l:T('Obey','照办'),out:[{t:T('The chestnut stall is closed the next day, and the next. You find you cannot eat chestnuts any more.','第二天栗子摊没开，第三天也没开。你发现自己再也吃不下栗子了。'),c:'bad',fx:{align:-8,merit:7,happy:-4}}]},
  {l:T('Warn the chestnut seller','给卖栗子的报信'),out:[{w:1,t:c=>T(`${c.npc.en} smiles. "Good. Branch 233 values mercy, sometimes." The chestnut seller was your inspector all along.`,`${c.npc.zh}笑了。"不错。二百三十三分坛有时也看重仁心。"原来卖栗子的一直就是盯你的人。`),c:'gold',fx:{align:4,merit:6}},{w:2,t:c=>T(`${c.npc.en} is gone by nightfall. The Society notices that its orders are leaking.`,`天黑前${c.npc.zh}就跑了。会里察觉到命令走漏了。`),c:'bad',fx:{align:6,flag:'dk_suspect'}}]},
  {l:T('Ask why','问为什么'),out:[{t:T('Nobody answers. The Night Owl Society never answers. The next order is addressed to someone else, about you.','没人回答。夜枭会从不回答。下一道命令发给了别人，内容是关于你的。'),c:'muted',fx:{merit:-3,happy:-2}}]}]});

I({id:'dk_ch_wudu',age:[10,80],cd:3,w:1.5,tags:DKC,when:s=>s.sect==='wudu',
 text:()=>T('You feed the Five Venoms at dawn: scorpion, centipede, toad, snake and spider. This morning the golden toad is missing.','天一亮你就去喂五毒：蝎子、蜈蚣、蟾蜍、蛇、蜘蛛。今早金蟾不见了。'),
 opts:[{l:T('Chase it into the village','追进村子'),out:[{w:2,t:T('You find it in a well bucket and carry it back in your hat.','你在井桶里找到了它，用帽子兜了回来。'),c:'good',fx:{merit:4}},{w:1,t:T('A little boy is about to lick it. You snatch it away just in time, and the boy’s mother hits you with a broom.','一个小男孩正要舔它。你一把抢下来，结果被孩子他娘拿扫帚打了一顿。'),c:'good',fx:{merit:3,align:4,happy:2}}]},
  {l:T('Swap in an ordinary toad','拿只普通蛤蟆顶替'),out:[{w:1,t:T('Nobody notices for a month. Then the elder tries to milk it for venom and gets only an offended croak.','一个月没人发现。后来长老去取蟾酥，只挤出一声委屈的呱。'),c:'bad',fx:{merit:-4,hurt:[3,8],cause:T('the elder’s anger','长老的怒火'),soft:1}},{w:1,t:T('It works. The ordinary toad lives a life of luxury.','居然成了。那只普通蛤蟆从此过上了好日子。'),c:'good',fx:{happy:3}}]},
  {l:T('Let it go','由它去'),out:[{t:T('Somewhere in the hills, a golden toad is free. You are docked a month’s merit.','山里某处，一只金蟾自由了。你被扣了一个月的贡献。'),c:'muted',fx:{merit:-3,align:1}}]}]});

I({id:'dk_ch_banquet',age:[16,80],cd:6,tags:DKC,when:dkEv,
 text:(c,s)=>T(`${dkL(s).en} throws a banquet for the hall masters. The cup in front of you smells faintly of almonds.`,`${dkL(s).zh}大宴各堂。你面前那杯酒隐隐有股杏仁味。`),
 opts:[{l:T('Drink it','喝'),out:[{w:3,t:T('It is almond wine. The lord watches you drain it and nods. Fearlessness is noted.','是杏仁酒。教主看着你一饮而尽，点了点头。胆量记下了。'),c:'good',fx:{merit:5,happy:2}},{w:1,t:T('It is not almond wine. You live, barely, and the lord is so impressed by your loyalty he sends you a doctor.','不是杏仁酒。你活了下来，差一点就没活。教主被你的忠心打动，派了大夫来。'),c:'bad',fx:{hurt:[12,28],cause:T('a poisoned cup','毒酒'),merit:8}}]},
  {l:T('Swap cups with the man beside you','和旁边的人换杯'),out:[{w:1,t:T('He drinks, laughs, and is fine. Then he notices whose cup it was.','他喝了，笑了，没事。然后他发现那是谁的杯子。'),c:'muted',fx:{enemy:1}},{w:1,t:T('He turns blue during the soup. The lord looks at you, and says nothing, and that is worse.','上汤的时候他脸色发青。教主看了你一眼，什么都没说，这才最可怕。'),c:'bad',fx:{align:-5,merit:2}}]},
  {l:T('Pour it into your sleeve','偷偷倒进袖子里'),out:[{w:s=>s.smarts/20,t:T('Smooth as silk. Your sleeve dissolves later, but you do not.','行云流水。后来袖子烂了，你没事。'),c:'good',fx:{smarts:1}},{w:1,t:T('The lord asks you to raise your cup again. It is empty. His smile is not.','教主让你再举杯。杯子空了。他的笑可不空。'),c:'bad',fx:{merit:-4,flag:'dk_suspect'}}]}]});

I({id:'dk_ch_spy',age:[14,80],cd:8,tags:DKC,when:dkEv,ctx:s=>{const c=scene();c.rk=dkRightK();c.npc=npc(s,{age:rint(20,30)});return c},
 text:c=>T(`You see the new recruit ${c.npc.en} burying a letter under the plum tree. It is addressed to ${dkST(c.rk).en}.`,`你看见新来的${c.npc.zh}在梅树下埋一封信。信是写给${dkST(c.rk).zh}的。`),
 opts:[{l:T('Expose the spy','揭发'),out:[{t:c=>T(`${c.npc.en} is dragged before the lord. You are rewarded and nobody trusts the new recruits for a year.`,`${c.npc.zh}被拖到教主面前。你得了赏，此后一年谁也不信新来的。`),c:'bad',fx:{merit:8,align:-5,money:30}}]},
  {l:T('Warn the spy to flee','叫他快逃'),out:[{w:2,t:T('By morning the bed is empty. You did not see anything.','天亮时床铺已经空了。你什么也没看见。'),c:'good',fx:{align:6}},{w:1,t:T('The spy runs too slowly, and talks too quickly.','他跑得太慢，招得太快。'),c:'bad',fx:{align:5,flag:'dk_suspect'}}]},
  {l:T('Blackmail the spy','借此敲诈'),out:[{t:T('Fifty taels a month for your silence. The spy pays and hates you, which is how the jianghu usually works.','每月五十两封口费。他照付，也恨你入骨。江湖大抵如此。'),c:'muted',fx:{money:50,align:-3,enemy:1}}]}]});

I({id:'dk_ch_suspect',age:[12,90],cd:1,w:4,need:'dk_suspect',tags:DKC,when:dkEv,ctx:s=>{const c=scene();c.npc=npc(s,{age:rint(45,65),lv:PW(1.0,6)(s)});return c},
 text:c=>T(`The Punishment Hall sends for you. ${c.npc.en}, its master, has a list of things that went wrong this year, and your name is beside most of them.`,`刑堂传你过去。刑堂堂主${c.npc.zh}手里有一张单子，记着今年出的岔子，大半旁边都写着你的名字。`),
 opts:[{l:T('Lie with a straight face','面不改色地撒谎'),out:[{w:s=>s.smarts/20+s.t.luck/4,t:T('Your story is so dull and so detailed that he falls asleep halfway through. You are cleared.','你编的故事又无聊又详细，他听到一半就睡着了。你过关了。'),c:'good',fx:{unflag:'dk_suspect',smarts:1}},{w:2,t:T('He has heard better lies from children. You are flogged and demoted in all but name.','这种谎话，孩子都说得比你好。你挨了鞭子，名义上没降职，实际上降了。'),c:'bad',fx:{unflag:'dk_suspect',merit:-6,hurt:[8,18],cause:T('the Punishment Hall','刑堂'),soft:1}}]},
  {l:T('Endure in silence','咬牙硬扛'),out:[{t:T('They run out of questions before you run out of silence. Your silence earns grudging respect, and scars.','问题都问完了，你还是一声不吭。这份沉默换来了几分敬意，和一身伤疤。'),c:'muted',fx:{unflag:'dk_suspect',hurt:[12,24],cause:T('the Punishment Hall','刑堂'),soft:1,merit:2}}]},
  {l:T('Fight your way out','杀出去'),sub:T('You will be a deserter.','你将成为叛徒。'),fight:FG((s,c)=>c.npc.lv,'injury',T('The Punishment Hall','刑堂'),T('the Punishment Hall','刑堂')),
   win:[{t:T('You go out through the window and do not stop running until the mountains are blue behind you.','你破窗而出，一直跑到身后的群山都变成了青色。'),c:'gold',fx:{unflag:'dk_suspect',align:5,f:s=>{if(s.sect)leaveSect(s)}}}],
   lose:[{t:T('They drag you back. The punishment is long and inventive.','你被拖了回去。刑罚漫长，花样百出。'),c:'bad',fx:{unflag:'dk_suspect',merit:-10,hurt:[10,20],cause:T('the Punishment Hall','刑堂'),soft:1}}]}]});

I({id:'dk_ch_mole',age:[14,90],cd:2,w:2.5,need:'dk_mole',tags:DKC,when:dkEv,
 text:(c,s)=>T(`A fruit seller you have never seen before gives you too much change. In the coins is a note from your righteous handler: "What is ${dkL(s).en} planning?"`,`一个从没见过的水果贩子多找了你几文钱。铜钱里夹着正道联络人的纸条："${dkL(s).zh}在谋划什么？"`),
 opts:[{l:T('Pass on the truth','据实回报'),out:[{w:3,t:T('Three weeks later a raid fails because the righteous were waiting. Nobody looks at you. Yet.','三个星期后，一次偷袭扑了空——正道早有准备。没人怀疑你。暂时。'),c:'good',fx:{align:5,money:40}},{w:1,t:T('The fruit seller is caught. He does not know your name, but he knows your face.','水果贩子被抓了。他不知道你的名字，却认得你的脸。'),c:'bad',fx:{align:4,flag:'dk_suspect'}}]},
  {l:T('Feed them lies','喂他们假消息'),sub:T('Become a true member after all.','从此真心归附。'),out:[{t:T('You send the righteous chasing ghosts, and tell the lord you did. He is delighted. Your handler stops writing.','你让正道扑了一场空，又把这事报给了教主。教主大喜。联络人再也没来过信。'),c:'bad',fx:{align:-6,merit:8,unflag:'dk_mole'}}]},
  {l:T('Lie low this year','今年按兵不动'),out:[{t:T('You eat the note. It tastes of plums and fear.','你把纸条吃了，一股李子味儿和恐惧的味道。'),c:'muted'}]}]});

I({id:'dk_mole_end',age:[16,90],once:1,w:5,need:'dk_mole',tags:DKC,when:s=>dkEv(s)&&s.age-s.flags.dk_mole>=3,
 text:(c,s)=>T(`The night has come. The righteous sects are at the foot of the mountain, waiting for the signal you promised. ${dkL(s).en} is drinking upstairs.`,`那一夜终于来了。正道各派聚在山脚，等你答应过的信号。${dkL(s).zh}正在楼上饮酒。`),
 opts:[{l:T('Open the gate','打开山门'),out:[{t:(c,s)=>T(`The hall burns. When the smoke clears you are a hero of the righteous, and ${dkS(s).en} will never forgive you, if any of it survives.`,`总坛烧起来了。烟散时，你成了正道的英雄。${dkS(s).zh}永远不会原谅你——如果它还剩下什么的话。`),c:'gold',fx:{fame:12,align:15,deed:T('Opened the gate of a dark faction to the righteous','卧底邪派，里应外合破其总坛'),f:s=>{if(s.sect)leaveSect(s);delete s.flags.dk_mole;delete s.flags.dk_pill;s.flags.deserter=s.age}}}]},
  {l:T('Warn the lord instead','反向教主告密'),out:[{t:T('The righteous walk into a trap. The lord raises you high and keeps you close, the way one keeps a knife.','正道一头撞进了埋伏。教主重用了你，把你放在身边——就像把一把刀放在身边。'),c:'bad',fx:{align:-15,merit:15,unflag:'dk_mole',enemy:1,f:s=>{if(s.rank<3)s.rank++}}}]},
  {l:T('Slip away in the confusion','趁乱脱身'),out:[{t:T('You leave both sides to their battle and walk away into the dark. Neither will ever quite trust you again.','你把两边都丢给那场厮杀，独自走进黑夜。从此谁也不会再全心信你。'),c:'muted',fx:{unflag:'dk_mole',f:s=>{if(s.sect)leaveSect(s)}}}]}]});

/* ====================== dark missions (sect) ====================== */
const DKM=['sect'];
const DKSAB=T('Alignment up, merit down. They may notice.','正气增，贡献减，可能被察觉。');
I({id:'dk_ms_kill',age:[16,75],cd:5,w:1.2,tags:DKM,when:dkEv,ctx:s=>{const c=scene();c.rk=dkRightK();c.npc=npc(s,{occ:19,age:rint(60,75),lv:PW(1.0,6)(s)});return c},
 text:c=>T(`Your orders: kill ${c.npc.en}, a retired master of ${dkST(c.rk).en} who now grows orchids in a valley and has made the mistake of writing a book about your faction.`,`命令是：杀了${dkST(c.rk).zh}的退隐高手${c.npc.zh}。他如今在山谷里种兰花，却犯了个错——写了本书，讲你们教里的事。`),
 opts:[{l:T('Carry it out','动手'),fight:FG((s,c)=>c.npc.lv,'injury',T('The orchid valley','兰花谷'),T('a retired master','退隐高手')),
   win:[{t:T('The orchids will go unwatered. The book is burned. You are paid, and praised, and you smell orchids in your sleep.','兰花再没人浇了，书也烧了。你拿了赏钱，得了夸奖，梦里却总闻到兰花香。'),c:'bad',fx:{merit:9,money:60,align:-6,wanted:1,fame:2}}],
   lose:[{t:T('The old man beats you with a trowel and sends you home with a pot of orchids "to calm your temper".','老人用花铲把你打了一顿，还送你一盆兰花"养养性子"。'),c:'muted',fx:{merit:-2,happy:2}}]},
  {l:T('Botch it on purpose','故意失手'),sub:DKSAB,out:[{t:T('You arrive loudly, trip over a flowerpot and give him time to vanish. You report a heroic struggle.','你大张旗鼓地闯进去，故意踢翻花盆，给他留足了逃跑的工夫。回去报告说经过一场恶战。'),c:'good',fx:{align:6,merit:-3,f:dkSus(.3)}}]},
  {l:T('Warn him and bring back his book','通风报信，只带回那本书'),out:[{w:2,t:T('He thanks you, gives you the only copy to burn, and a sword he no longer needs.','他谢过你，把唯一的书稿交给你去烧，还送了你一柄他用不着的剑。'),c:'good',fx:{align:8,merit:2,item:'steelsword',f:dkSus(.35)}},{w:1,t:T('He burns the book himself and leaves a note in it, addressed to your lord, signed with your name.','他自己把书烧了，还留了一张给你们教主的条子，落款写的是你的名字。'),c:'bad',fx:{align:6,flag:'dk_suspect'}}]}]});

I({id:'dk_ms_kidnap',age:[16,70],cd:6,tags:DKM,when:dkEv,ctx:s=>{const c=scene();c.npc=npc(s,{occ:12,sex:'f',age:rint(16,22)});c.g=npc(s,{occ:8,age:rint(30,45),lv:PW(.95,5)(s)});return c},
 text:c=>T(`You are to kidnap ${c.npc.en}, daughter of a salt merchant, for ransom. She travels with a bodyguard, ${c.g.en}.`,`你奉命绑走盐商的千金${c.npc.zh}，换赎金。她身边跟着护卫${c.g.zh}。`),
 opts:[{l:T('Fight the bodyguard','对付护卫'),fight:FG((s,c)=>c.g.lv,'injury',T('Kidnapping','绑票'),T('a bodyguard','护卫'),c=>T(c.g.en,c.g.zh)),
   win:[{w:2,t:T('The ransom is paid in three days. She is returned without a scratch and with a long list of complaints about the food.','三天后赎金到了。她毫发无伤地回了家，还列了一长串对伙食的意见。'),c:'bad',fx:{merit:7,money:80,align:-6,wanted:1}},{w:1,t:T('It turns out she was running away from an arranged marriage. She refuses to be ransomed and asks to join you.','原来她正想逃婚。她不肯被赎回去，还要跟你们入伙。'),c:'gold',fx:{merit:5,meet:'friend',bond:65,happy:4}}],
   lose:[{t:T('The bodyguard ties you up with your own rope and leaves you at the yamen gate.','护卫拿你自己带的绳子把你捆了，扔在县衙门口。'),c:'bad',fx:{merit:-2,wanted:1}}]},
  {l:T('Let her "escape" on the road','半路让她"逃走"'),sub:DKSAB,out:[{t:T('You fall asleep on watch, loudly. When you wake, the rope has been cut with your own knife, which was left conveniently near her.','你守夜时"睡着"了，鼾声如雷。醒来时绳子被割断了——用的正是你"恰好"放在她身边的刀。'),c:'good',fx:{align:6,merit:-3,f:dkSus(.3)}}]}]});

I({id:'dk_ms_rob',age:[16,70],cd:5,w:1.2,tags:DKM,when:dkEv,ctx:s=>{const c=scene();c.npc=npc(s,{occ:8,age:rint(35,55),lv:PW(1.05,8)(s)});return c},
 text:c=>T(`An escort convoy is carrying silver through ${c.place.en}. Escort chief ${c.npc.en} rides at the front. Your faction wants the silver.`,`一支镖队押着银子经过${c.place.zh}，总镖头${c.npc.zh}骑马走在最前头。教里看上了这批银子。`),
 opts:[{l:T('Rob the convoy','劫镖'),fight:FG((s,c)=>c.npc.lv,'injury',T('Robbing the escort','劫镖'),T('an escort chief','总镖头')),
   win:[{t:T('The escorts scatter. The silver goes up the mountain; a share of it stays in your boots.','镖师四散。银子上了山，有一份落进了你的靴筒。'),c:'bad',fx:{merit:8,money:120,align:-5,wanted:1}}],
   lose:[{t:T('The escort chief plants his banner in the road and you leave without the silver, or your dignity.','总镖头把镖旗往路中间一插，你连银子带脸面都没拿到。'),c:'bad',fx:{merit:-2}}]},
  {l:T('Tip off the escort the night before','前一晚给镖局报信'),sub:DKSAB,out:[{t:T('The convoy takes another road. Your faction waits all day at an empty pass, and wonders.','镖队改了道。你们在空荡荡的山口等了一整天，心里犯起了嘀咕。'),c:'good',fx:{align:7,merit:-4,f:dkSus(.35)}}]},
  {l:T('Rob it, and keep the silver for yourself','劫了，私吞'),out:[{w:1,t:T('You report the convoy was empty. You buy a very quiet house far away.','你回报说那是空镖。你在很远的地方悄悄置了一处宅子。'),c:'gold',fx:{money:300,align:-5,flag:'dk_suspect'}},{w:1,t:T('The escort chief recognises you at the faction’s gate a month later, selling the silver back.','一个月后，总镖头在你们山门前认出了你——你正把银子往回卖。'),c:'bad',fx:{money:100,align:-5,wanted:1,flag:'dk_suspect'}}]}]});

I({id:'dk_ms_burn',age:[16,70],cd:6,tags:DKM,when:dkEv,ctx:s=>{const c=scene();c.rk=chance(.5)?dkRivalK(s):dkRightK();return c},
 text:c=>T(`Your orders: burn the hall of ${dkST(c.rk).en} in the next county, tonight.`,`命令是：今夜烧了邻县${dkST(c.rk).zh}的分舵。`),
 opts:[{l:T('Burn it','放火'),out:[{w:2,t:T('The hall goes up like dry straw. You watch from a hill and feel nothing, which is the worst part.','分舵像干草一样烧了起来。你在山坡上看着，心里什么感觉都没有——这才是最糟的。'),c:'bad',fx:{merit:8,align:-6}},{w:1,t:T('The wind turns. Half the town burns with it. Even your lord is uneasy.','风向变了，半个镇子跟着烧了。连教主都有些不安。'),c:'bad',fx:{merit:6,align:-12,wanted:1,happy:-6}}]},
  {l:T('Check the building for people first','先进去看看有没有人'),out:[{t:T('You carry out a sleeping cook and two children before you strike the flint. The fire is just as big. You sleep better.','点火之前，你背出了一个熟睡的厨子和两个孩子。火照样很大，你却睡得踏实了些。'),c:'good',fx:{merit:6,align:5}}]},
  {l:T('Sell the plan to the target','把计划卖给对方'),out:[{w:1,t:T('They pay a hundred taels and set a trap for your own people. You were "lucky" to be the one who escaped.','对方付了一百两，给你们自己人设了个圈套。你"走运"成了唯一逃出来的那个。'),c:'muted',fx:{money:100,merit:-3,f:dkSus(.5)}},{w:1,t:T('They take the warning, then your silver, then you, and send you back with a note.','他们收下了消息，又收了你的银子，最后连你也扣下，捎了张字条把你送了回去。'),c:'bad',fx:{hurt:[6,14],cause:T('a beating','一顿毒打'),soft:1,flag:'dk_suspect'}}]}]});

I({id:'dk_ms_frame',age:[16,70],cd:6,tags:DKM,when:dkEv,ctx:s=>{const c=scene();c.rk=dkRightK();c.npc=npc(s,{occ:13,age:rint(25,40)});return c},
 text:c=>T(`${c.npc.en} is the rising hero of ${dkST(c.rk).en}. Your orders: plant a faction token and a bag of stolen gold in ${c.npc.his} room, and let the righteous do the rest.`,`${c.npc.zh}是${dkST(c.rk).zh}新出的少年英雄。命令是：把本教令牌和一袋赃金塞进${c.npc.ta}房里，剩下的交给正道自己去办。`),
 opts:[{l:T('Plant it','照办'),out:[{t:c=>T(`${c.npc.en} is expelled before the month is out. ${c.npc.His} own master leads the trial. You are paid well, and it tastes like ash.`,`不出一个月，${c.npc.zh}就被逐出了师门，审${c.npc.ta}的正是${c.npc.ta}自己的师父。你得了重赏，却味同嚼蜡。`),c:'bad',fx:{merit:8,money:50,align:-8}}]},
  {l:T('Plant it clumsily, on purpose','故意栽得很蠢'),sub:DKSAB,out:[{t:T('The token is upside down and the gold has your faction’s seal on every bar. Even the righteous see through it. The hero’s name is cleared.','令牌倒着放，金条上都烙着本教的印记。连正道都看得出是栽赃。少侠洗清了冤屈。'),c:'good',fx:{align:6,merit:-3,f:dkSus(.3)}}]},
  {l:T('Warn the hero','给少侠报信'),out:[{t:c=>T(`${c.npc.en} listens, then bows to you. "When you want out, come to me."`,`${c.npc.zh}听完，向你一揖。"哪天你想脱身，来找我。"`),c:'good',fx:{align:8,meet:'friend',bond:60,merit:-3,f:dkSus(.4)}}]}]});

I({id:'dk_ms_shaolin',age:[18,70],cd:10,w:.8,tags:DKM,when:s=>dkEv(s)&&power(s)>=40,ctx:s=>{const c=scene();c.npc=npc(s,{occ:4,age:rint(70,90),lv:PW(1.5,25)(s)});return c},
 text:()=>T('Your lord wants a manual from the Scripture Pavilion of Shaolin. The monks guard it with arhat arrays, and with an old monk who sweeps the floor.','教主要你去偷少林藏经阁的秘籍。少林以罗汉阵护阁，还有一个扫地的老和尚。'),
 opts:[{l:T('Sneak in by night','夜里潜入'),out:[{w:s=>s.t.luck+s.t.wit,t:T('You come out with the Vajra Finger manual under your shirt and a copy of it in your head.','你揣着《金刚指》的秘籍出来了，脑子里还记下了一份。'),c:'gold',fx:{merit:12,fame:3,align:-4,art:'vajra'}},{w:8,t:T('An old monk sweeping the stairs looks up. "The manuals are heavy," he says, "and you are carrying too much already." He taps you once with his broom. You wake outside the gate, unhurt, and a little ashamed.','台阶上扫地的老僧抬起头。"经书很重，"他说，"你身上背的已经太多了。"他用扫帚轻轻点了你一下。你在山门外醒来，毫发无伤，却有些惭愧。'),c:'muted',fx:{merit:-2,align:4,qi:3}}]},
  {l:T('Fight your way past the old sweeper','打倒扫地老僧闯进去'),fight:FG((s,c)=>c.npc.lv,'injury',T('The sweeping monk','扫地老僧'),T('the sweeping monk','扫地老僧'),()=>T('the sweeping monk','扫地老僧')),
   win:[{t:T('Impossible, and yet. You leave with a manual and a feeling that he let you.','不可能，可你做到了。你带着秘籍离开，总觉得是他有意放你。'),c:'gold',fx:{merit:15,fame:6,align:-6,wanted:2,art:'roar'}}],
   lose:[{t:T('He sets your bones himself and feeds you rice gruel for a week. "Go home," he says. "And think about what home is."','他亲手给你接了骨，喂了你一个星期的白粥。"回去吧，"他说，"好好想想哪里才是家。"'),c:'muted',fx:{align:5,merit:-3,qi:4}}]},
  {l:T('Write a fake manual yourself','自己编一本假秘籍'),out:[{w:s=>s.smarts/20,t:T('Your "Shaolin Hundred-Step Mystic Palm" is studied by the whole hall. Nobody improves, but nobody admits it.','你编的《少林百步神掌》全堂上下都在练。谁也没练出什么名堂，可谁也不肯承认。'),c:'good',fx:{merit:7,smarts:3}},{w:2,t:T('The lord tries the first move and dislocates his shoulder.','教主照着练了第一式，肩膀脱了臼。'),c:'bad',fx:{merit:-5,hurt:[8,16],cause:T('the lord’s shoulder, and temper','教主的肩膀，和他的脾气')}}]}]});

I({id:'dk_ms_well',age:[16,70],cd:6,tags:DKM,when:s=>dkEv(s)&&['wudu','xingxiu','sunmoon','erengu','haisha','haijiao','tuoling'].includes(s.sect),
 text:()=>T('A rich town refuses to pay tribute. You are given a packet of powder for its well and told the antidote will cost them a thousand taels.','一座富镇不肯交供奉。上头给了你一包药粉，叫你倒进镇上的井里，解药卖他们一千两。'),
 opts:[{l:T('Poison the well','下毒'),out:[{t:T('The town pays within the week. You do not go to see the people who drank first.','不出七天，镇上就交了钱。最先喝水的那些人，你没去看。'),c:'bad',fx:{merit:8,money:100,align:-12}}]},
  {l:T('Pour in herbs instead','换成草药倒进去'),sub:DKSAB,out:[{t:T('The town’s coughs clear up. The tribute never comes. Your hall master swears at the powder supplier.','镇上人的咳嗽都好了。供奉一文没来。堂主把配药的人骂了个狗血淋头。'),c:'good',fx:{align:7,merit:-3,f:dkSus(.3)}}]},
  {l:T('Warn the town elders','告诉镇上的长老'),out:[{w:1,t:T('They hire guards for the well and slip you a purse. The faction finds out who.','他们给井派了守卫，又塞给你一袋银子。教里查到了是谁。'),c:'muted',fx:{align:6,money:40,flag:'dk_suspect'}},{w:1,t:T('They do not believe you and run you out of town. The well stays clean anyway.','他们不信你，把你赶出了镇子。不过井到底还是干净的。'),c:'muted',fx:{align:5}}]}]});

I({id:'dk_ms_debt',age:[16,70],cd:5,tags:DKM,when:dkEv,ctx:s=>{const c=scene();c.npc=npc(s,{occ:8,age:rint(45,60),lv:PW(.9,4)(s)});return c},
 text:c=>T(`${c.npc.en}, who runs a respectable escort agency, borrowed from your faction in a bad year. Now it is your job to collect, with interest.`,`开着一家正经镖局的${c.npc.zh}，在年景不好时向你们教里借过钱。如今轮到你去连本带利地收回来。`),
 opts:[{l:T('Demand payment, sword drawn','拔剑讨债'),fight:FG((s,c)=>c.npc.lv,'light',T('Debt collection','讨债'),T('an escort master','镖头')),
   win:[{t:T('He pays, and takes down his banner the same week. Thirty years of reputation, gone in an afternoon.','他还了钱，同一周就摘了镖旗。三十年的名声，一个下午就没了。'),c:'bad',fx:{merit:6,money:50,align:-4}}],
   lose:[{t:T('He sends you back with the principal only and a message: "Interest is for bankers."','他只还了本金，让你带句话回去："利息是钱庄才收的。"'),c:'muted',fx:{merit:2,money:20}}]},
  {l:T('Take his best horse instead','牵走他最好的马抵债'),out:[{t:T('The horse is magnificent. Your hall master takes it, and gives you the saddle.','那匹马神骏非凡。堂主把马收了，给了你马鞍。'),c:'muted',fx:{merit:4,align:-2}}]},
  {l:T('Extend his loan and pay the interest yourself','替他续借，利息你垫'),cost:40,out:[{t:T('He never knows. Years later, his agency escorts your coffin for free, but that is another story.','他始终不知道这事。多年后他的镖局分文不取地替你押过一次镖，那是后话了。'),c:'good',fx:{align:5,merit:2}}]}]});

I({id:'dk_ms_rescue',age:[18,75],cd:12,w:.8,tags:DKM,when:dkEv,ctx:s=>{const c=scene();c.npc=npc(s,{occ:9,age:rint(35,55),lv:PW(1.05,8)(s)});return c},
 text:()=>T('A former guardian of your faction has been chained in a dungeon beneath West Lake for twelve years. Your lord wants him freed. Or says he does.','本教一位前任护法被锁在西湖底的地牢里，已经十二年了。教主要你去救他出来——至少嘴上是这么说的。'),
 opts:[{l:T('Fight the jailers','硬闯地牢'),fight:FG((s,c)=>c.npc.lv,'injury',T('Beneath West Lake','西湖地牢'),T('the jailers of West Lake','西湖地牢的狱卒')),
   win:[{w:2,t:T('The old guardian blinks at the daylight, laughs, and taps your back. Something warm runs through your meridians.','老护法眯着眼看天光，大笑一声，在你背上一拍。一股暖流贯通了你的经脉。'),c:'gold',fx:{merit:10,qi:8}},{w:1,t:T('The old guardian walks straight to the lord’s hall and takes his chair back. You, his rescuer, rise with him.','老护法径直走进总坛，夺回了教主之位。你这个救命恩人，跟着他平步青云。'),c:'gold',fx:{merit:12,f:s=>{if(s.rank<3)s.rank++}}}],
   lose:[{t:T('You get as far as the third door. The lake is very cold on the way out.','你只闯到了第三道门。逃出来时，湖水冰冷刺骨。'),c:'bad',fx:{merit:-2,ill:'cold'}}]},
  {l:T('Bribe the four jailers with art','投其所好，买通四位庄主'),if:s=>s.smarts>=45,out:[{w:s=>s.smarts/20,t:T('The four masters of the lake manor love chess, calligraphy, painting and music. You lose to each of them, gracefully, and walk out with the prisoner.','西湖梅庄四位庄主分别好棋、好书、好画、好琴。你一一"惜败"，体体面面地带走了犯人。'),c:'gold',fx:{merit:10,smarts:3}},{w:2,t:T('You beat the chess master by accident. He has you thrown in the lake.','你一不小心下赢了那位棋痴。他叫人把你扔进了湖里。'),c:'muted',fx:{merit:-1,ill:'cold'}}]},
  {l:T('Report him dead','回报说他已经死了'),out:[{t:T('Your lord seems relieved, which tells you everything about why you were sent.','教主似乎松了一口气。这下你全明白了，为什么派的是你。'),c:'muted',fx:{merit:3,smarts:2}}]}]});

I({id:'dk_ms_recruit',age:[18,75],cd:6,tags:DKM,when:dkEv,ctx:s=>{const c=scene();c.npc=npc(s,{occ:pick([20,21]),age:rint(9,12)});return c},
 text:c=>T(`You are sent to bring back a talented child: ${c.npc.en}, an orphan who can climb anything and has already bitten two constables.`,`上头派你去带个有天分的孩子回来：孤儿${c.npc.zh}，什么都爬得上去，已经咬过两个捕快了。`),
 opts:[{l:T('Take the child to the faction','带回教中'),out:[{t:T('The child is placed with the poison hall. You see them once a year after that, a little colder each time.','孩子被分进了毒堂。此后你每年见一回，一回比一回冷。'),c:'bad',fx:{merit:5,align:-4}}]},
  {l:T('Tell the child to run','叫孩子快跑'),sub:DKSAB,out:[{t:T('The child runs, then comes back to steal your purse, then runs again. You report that the child was too fast.','孩子跑了，又折回来偷了你的钱袋，又跑了。你回报说孩子跑得太快。'),c:'good',fx:{align:5,merit:-2,money:-10,f:dkSus(.2)}}]},
  {l:T('Take the child as your own disciple','收作自己的徒弟'),out:[{t:T('The child bites you too, then decides you will do. You have a disciple.','孩子也咬了你一口，然后决定跟你了。你有了一个徒弟。'),c:'good',fx:{merit:3,meet:'disciple',bond:55}}]}]});

I({id:'dk_ms_hero',age:[18,70],cd:8,tags:DKM,when:dkEv,ctx:s=>{const c=scene();c.npc=npc(s,{occ:13,age:rint(40,60),lv:PW(1.1,8)(s)});return c},
 text:c=>T(`The righteous sects are holding a heroes’ conference. You are sent in disguise to listen. The host is ${c.npc.en}.`,`正道各派召开英雄大会。你乔装混了进去打探消息。东道主是${c.npc.zh}。`),
 opts:[{l:T('Listen quietly','安静打探'),out:[{w:3,t:T('You learn who hates whom and who owes whom. The lord is pleased with the list.','谁恨谁、谁欠谁，你都摸清了。教主看了名单很满意。'),c:'good',fx:{merit:6,smarts:2}},{w:1,t:T('A beggar sect elder smells the incense of your faction on you. You leave by the roof.','丐帮一位长老闻出你身上有本教的香火味。你从房顶溜了。'),c:'bad',fx:{merit:2,hurt:[4,10],cause:T('a beggar’s staff','青竹棒')}}]},
  {l:T('Spread rumours','散布谣言'),out:[{t:T('By the third day two sects are no longer speaking. The conference ends early. Your lord laughs until he coughs.','到第三天，两派已经互不理睬，大会提前散了。教主笑得直咳嗽。'),c:'bad',fx:{merit:8,align:-4}}]},
  {l:T('Throw off the disguise and challenge the host','亮明身份，挑战东道主'),fight:FG((s,c)=>c.npc.lv,'injury',T('Heroes’ conference','英雄大会'),T('the host of the heroes’ conference','英雄大会东道主')),
   win:[{t:T('You beat the host in front of every sect in the land and walk out through a wall of drawn swords. Nobody dares to stop you.','你当着天下各派击败了东道主，从一片出鞘的剑丛中走了出去，没人敢拦。'),c:'gold',fx:{merit:10,fame:8,align:-4,wanted:1}}],
   lose:[{t:T('You are thrown out of the hall, which is the kindest thing that could have happened.','你被扔出了大厅——这已经是最客气的下场了。'),c:'bad',fx:{merit:-2,fame:-2}}]}]});

I({id:'dk_ms_tribute',age:[16,70],cd:5,tags:DKM,when:dkEv,ctx:s=>{const c=scene();c.npc=npc(s,{occ:9,age:rint(35,55),lv:PW(.9,4)(s)});return c},
 text:()=>T('You are sent to collect the yearly tribute from a fishing village. It was a bad year. The children are thin.','你奉命去一个渔村收年贡。今年收成不好，孩子们都瘦得很。'),
 opts:[{l:T('Take the tribute','照收'),out:[{t:T('You take their dried fish and their silver. An old fisherman watches you leave and does not curse, which is worse.','你收走了他们的鱼干和银子。一个老渔夫看着你走，没骂你——这更难受。'),c:'bad',fx:{merit:5,money:30,align:-6}}]},
  {l:T('Rob the magistrate instead','去抢县官的'),fight:FG((s,c)=>c.npc.lv,'light',T('The magistrate’s strongbox','县官的银箱'),T('the magistrate’s men','县衙差役')),
   win:[{t:T('The magistrate’s strongbox pays the village’s tribute twice over. The village sends you a barrel of fish.','县官的银箱足够付两倍的年贡。渔村送了你一桶鱼。'),c:'gold',fx:{merit:6,money:60,align:4,wanted:1}}],
   lose:[{t:T('You come back with nothing and a black eye. The faction takes the tribute from the village anyway.','你空手而归，还挨了一拳。教里照样派人去渔村收了贡。'),c:'bad',fx:{merit:-2}}]},
  {l:T('Pay it from your own purse','自掏腰包替他们交'),cost:40,out:[{t:T('You hand in the tribute and say nothing. That winter, the village names a boat after you.','你交了贡，一句话也没说。那年冬天，渔村拿你的名字给一条船起了名。'),c:'good',fx:{merit:4,align:6,fame:1}}]}]});

/* ====================== leaving: the hunt and the way back ====================== */
I({id:'deserter_hunt',age:[14,90],w:5,once:1,need:'deserter',when:s=>s.age-s.flags.deserter>=2&&s.sect!==s.dkFrom,ctx:s=>{const c=scene();c.npc=npc(s,{age:rint(30,50),lv:PW(1.05,8)(s)});c.old=dkOld(s);return c},
 text:c=>T(`${c.intro.en}, at ${c.place.en}, three figures in black step out of the shadows. Their leader, ${c.npc.en}, holds up a token of ${c.old.en}. "Nobody leaves. You knew that."`,`${c.intro.zh}，${c.place.zh}，三个黑衣人从暗处走了出来。为首的${c.npc.zh}亮出一块${c.old.zh}的令牌。"没人能走。你知道的。"`),
 opts:[{l:T('Fight to the death','拼死一战'),fight:FG((s,c)=>c.npc.lv,'death',T('The deserter’s reckoning','叛徒的清算'),T('killers sent after a deserter','追杀叛徒的杀手')),
   win:[{t:c=>T(`You leave three bodies at ${c.place.en} and a message carved on a tree. Word spreads: those who hunt you do not come back. The killers stop coming.`,`你在${c.place.zh}留下三具尸首，又在树上刻了一句话。消息传开了：追杀你的人都没回去。从此再没有杀手来过。`),c:'gold',fx:{fame:5,unflag:'deserter',deed:T('Survived the killers of a dark faction','从邪派的追杀中活了下来')}}],
   lose:[{t:T('They leave you for dead in a ditch. Perhaps they believe it. For now, they do not come back.','他们把你丢在沟里等死。也许他们真以为你死了。至少眼下，他们没再来。'),c:'bad',fx:{unflag:'deserter',maxHealth:-3}}]},
  {l:T('Run','逃'),out:[{w:s=>s.t.luck,t:T('You run through the night, change your name in the next province, and grow a beard or cut your hair. They lose the trail.','你连夜奔逃，到了邻省改名换姓，蓄了胡子或剪了头发。他们跟丢了。'),c:'good',fx:{unflag:'deserter',happy:-4,fame:-3}},{w:3,t:T('They catch you at a river crossing. You escape into the water, leaving blood behind.','他们在渡口追上了你。你跳进了河里，身后一路血迹。'),c:'bad',fx:{unflag:'deserter',hurt:[15,35],cause:T('killers sent after a deserter','追杀叛徒的杀手')}}]},
  {l:T('Buy your life','花钱买命'),cost:300,out:[{w:2,t:T('They count the silver twice. "We never found you." They are, after all, employees.','他们把银子数了两遍。"我们没找到你。"说到底，他们也只是打工的。'),c:'muted',fx:{unflag:'deserter'}},{w:1,t:T('They take the silver and a finger, "so the lord believes us". It is a fair price, they say.','他们收了银子，又切了你一根手指，"好让教主相信"。他们说这很公道。'),c:'bad',fx:{unflag:'deserter',hurt:[8,15],cause:T('killers sent after a deserter','追杀叛徒的杀手'),looks:-2}}]},
  {l:T('Stand with your new sect','请师门出头'),if:s=>dkRt(s),out:[{t:T('Your fellow disciples step out behind you, swords drawn. The killers count, and leave. Your sect has taken a side in public, and it is yours.','师兄弟们拔剑站到了你身后。杀手们数了数人头，走了。师门当众站了你这边。'),c:'good',fx:{unflag:'deserter',merit:3,align:3}}]},
  {l:T('Go back and beg','回去求饶'),if:s=>!s.sect&&!s.org&&isEvil(s.dkFrom),out:[{t:T('You crawl the last mile on your knees. They take you back, after the Punishment Hall has had its turn.','最后一里路，你是跪着爬上去的。刑堂用过刑之后，他们收下了你。'),c:'bad',fx:{unflag:'deserter',hurt:[15,28],cause:T('the Punishment Hall','刑堂'),soft:1,align:-6,f:s=>{if(!s.sect&&s.dkFrom){joinSect(s,s.dkFrom);delete s.flags.dk_pill}}}}]}]});

I({id:'dk_repent',age:[16,65],once:1,w:1.5,need:'deserter',when:s=>dkFree(s)&&s.age-s.flags.deserter>=1,ctx:s=>{const c=scene();c.k=s.gender==='f'?pick(['emei','wudang']):pick(['shaolin','wudang']);c.npc=npc(s,{occ:c.k==='shaolin'?4:c.k==='emei'?3:2,age:rint(55,75)});return c},
 text:c=>T(`You climb the steps of ${dkST(c.k).en}. The gatekeeper, ${c.npc.en}, knows exactly what you were. "Why are you here?"`,`你登上${dkST(c.k).zh}的石阶。守门的${c.npc.zh}很清楚你从前是什么人。"你来做什么？"`),
 opts:[{l:T('Kneel at the gate until they answer','长跪山门，直到他们答复'),out:[{w:s=>s.t.heart+2,t:c=>T(`You kneel for three days in the rain. On the fourth morning the abbot himself lifts you up. "The sea of bitterness has no shore; turn your head and there is the bank." You are a disciple of ${dkST(c.k).en}.`,`你在雨里跪了三天。第四天清晨，掌门亲自扶起了你。"苦海无边，回头是岸。"你成了${dkST(c.k).zh}的弟子。`),c:'gold',fx:{align:15,deed:T('Left the dark path and was taken in by a righteous sect','弃暗投明，拜入正派'),f:(s,c)=>{if(!s.sect)joinSect(s,c.k)}}},
   {w:3,t:T('On the third day they carry you down the mountain with a fever. "Not yet," says the note pinned to your coat.','第三天，你发着高烧被抬下了山。衣襟上别着一张字条："时候未到。"'),c:'muted',fx:{align:5,ill:'fever'}}]},
  {l:T('Confess everything, in public','当众忏悔一切'),out:[{w:2,t:c=>T(`You name every crime. Some in the crowd weep; a few throw stones. The abbot accepts you, on condition you spend a year carrying water. You are a disciple of ${dkST(c.k).en}.`,`你把每一桩罪行都说了出来。人群里有人落泪，也有人扔石头。掌门收下了你，条件是先挑一年的水。你成了${dkST(c.k).zh}的弟子。`),c:'gold',fx:{align:18,fame:-3,hurt:[3,8],cause:T('stones from a crowd','人群扔的石头'),f:(s,c)=>{if(!s.sect)joinSect(s,c.k)}}},
   {w:1,t:T('A woman in the crowd recognises you as the one who burned her village. The gates close. You do not argue.','人群里一个女人认出你就是烧了她村子的人。山门关上了。你没有争辩。'),c:'bad',fx:{align:8,happy:-8}}]},
  {l:T('Turn back','转身离开'),out:[{t:T('Some doors you are not ready to walk through.','有些门，你还没准备好跨进去。'),c:'muted'}]}]});

I({id:'dk_double',age:[18,60],once:1,w:1.2,need:'deserter',when:s=>dkFree(s)&&isEvil(s.dkFrom)&&s.age-s.flags.deserter>=1,ctx:s=>{const c=scene();c.npc=npc(s,{occ:9,age:rint(40,55)});c.old=dkOld(s);return c},
 text:c=>T(`A man in the uniform of the Embroidered Guard, ${c.npc.en}, sits beside you and speaks without looking at you. "You know ${c.old.en} from the inside. Go back. Be our eyes. When it falls, you will be a free and honoured person."`,`一个锦衣卫打扮的人${c.npc.zh}坐到你身边，眼睛看着别处说话。"${c.old.zh}里头的门道你最清楚。回去，做我们的眼睛。等它倒了，你就是清清白白、有功之人。"`),
 opts:[{l:T('Go back as a spy','回去做卧底'),sub:T('Rejoin your old faction in secret service.','重回旧派，暗中为正道效力。'),out:[{t:T('You crawl back to the gate with a story about regret. They flog you, and take you back. Your real work begins.','你带着一套"悔不当初"的说辞爬回山门。他们抽了你一顿，收下了你。真正的差事这才开始。'),c:'gold',fx:{money:100,hurt:[8,16],cause:T('the Punishment Hall','刑堂'),soft:1,unflag:'deserter',f:s=>{if(!s.sect&&s.dkFrom){joinSect(s,s.dkFrom);delete s.flags.dk_pill;s.flags.dk_mole=s.age}}}}]},
  {l:T('Refuse','拒绝'),out:[{t:T('"Then we never met." He pays for your tea and is gone.','"那就当我们没见过。"他付了你的茶钱，走了。'),c:'muted'}]}]});

I({id:'dk_pillwake',age:[10,95],once:1,w:5,need:'dk_pill',when:s=>s.sect!=='sunmoon'&&s.age-s.flags.dk_pill>=1,
 text:()=>T('Dragon Boat Festival comes, and no antidote with it. Something stirs behind your eyes. The Heart-Eating Pill is waking up.','端午到了，解药却没有来。你眼睛后面有什么东西在动。噬心丹醒了。'),
 opts:[{l:T('Swallow the spare dose','吞下备用的那颗'),if:s=>!!s.flags.dk_spare,out:[{t:T('The spare dose you sewed into your collar buys you a year, and a year is long enough to find a better doctor. You do.','缝在衣领里的那颗解药给你争来了一年。一年，够找一位更好的大夫了。你找到了。'),c:'good',fx:{unflag:['dk_pill','dk_spare']}}]},
  {l:T('Find the Killer Doctor Ping','去找"杀人名医"平一指'),cost:400,out:[{w:3,t:T('Doctor Ping saves one life for every one he takes. He takes your silver and, with a long silver needle, the worms. "Now go and kill someone for me," he jokes. You hope he is joking.','平一指救一人便杀一人。他收了你的银子，用一根长银针挑出了尸虫。"现在你替我去杀个人。"他开玩笑道。你希望他是开玩笑。'),c:'good',fx:{unflag:'dk_pill',hurt:[4,10],cause:T('a long silver needle','长银针')}},{w:1,t:T('He is out of town. His apprentice tries. You live, but something is gone from your memory, and you will never know what.','他出门了，徒弟替他下的针。你活了下来，可记忆里少了点什么，你永远不会知道是什么。'),c:'bad',fx:{unflag:'dk_pill',smarts:-6,hurt:[6,12],cause:T('the corpse-worms','噬心蛊'),soft:1}}]},
  {l:T('Force the worms out with inner energy','以内力逼出尸虫'),out:[{w:s=>s.qi/15+(s.flags.dk_recipe?3:0),t:T('You sit for nine days. On the tenth you vomit up three grey worms, and laugh until you cry.','你一坐九天。第十天，你吐出三条灰白的虫子，笑着笑着就哭了。'),c:'gold',fx:{unflag:'dk_pill',qi:6}},{w:3,t:T('The worms are stronger than your qi. You live, but your mind is never quite as clear again.','尸虫比你的内力还强。你活了下来，可脑子再也没有从前清楚了。'),c:'bad',fx:{unflag:'dk_pill',hurt:[20,40],cause:T('the Heart-Eating Pill','噬心丹'),smarts:-8}}]},
  {l:T('Crawl back to Soul-Severing Cliff','爬回断魂崖'),if:s=>!s.sect&&!s.org,out:[{t:T('They give you the antidote, and take everything else. You are a follower of the Crimson Sky Cult again.','他们给了你解药，拿走了你的一切。你又成了赤霄教的教众。'),c:'bad',fx:{unflag:['dk_pill','deserter'],align:-8,f:s=>{if(!s.sect)joinSect(s,'sunmoon')}}}]}]});

/* ====================== righteous disciples, tempted or framed ====================== */
I({id:'dk_rt_framed',age:[14,70],cd:15,tags:DKC,when:dkRt,ctx:s=>{const c=scene();c.npc=npc(s,{age:s.age+rint(1,8),lv:PW(1.0,5)(s)});return c},
 text:c=>T(`A black wooden token of the Crimson Sky Cult is found under your pillow. Your senior ${c.npc.en} found it, very quickly, as if ${c.npc.he} knew where to look.`,`有人在你枕头底下搜出一块赤霄教的赤霄令。是师兄${c.npc.zh}搜出来的，快得很，好像早知道在哪儿。`),
 opts:[{l:T('Demand a trial by combat','要求以武证清白'),fight:FG((s,c)=>c.npc.lv,'light',T('Trial by combat','以武证清白'),T('a trial by combat','比武自证')),
   win:[{t:c=>T(`You win, and in the scuffle a second token falls out of ${c.npc.en}’s sleeve. The elders go very quiet.`,`你赢了。混战中，又一块赤霄令从${c.npc.zh}袖子里掉了出来。长老们一下子都不作声了。`),c:'good',fx:{merit:6,fame:2,meet:'enemy',bond:5}}],
   lose:[{t:T('You lose. "Heaven has judged," says an elder, which is not how heaven works. You are confined to the cliff for a year.','你输了。"天意如此。"一位长老说——天意可不是这么用的。你被罚去面壁崖面壁一年。'),c:'bad',fx:{merit:-6,happy:-6,qi:3}}]},
  {l:T('Find the real spy','揪出真内奸'),out:[{w:s=>s.smarts/15,t:c=>T(`You notice the ink on the token is fresh and the carving matches ${c.npc.en}’s knife. The real spy is expelled; you are thanked, briefly.`,`你注意到令牌上的墨迹还新，刻痕与${c.npc.zh}的小刀吻合。真内奸被逐出师门，你得了一句简短的谢意。`),c:'good',fx:{merit:8,smarts:2}},{w:2,t:T('Your theory is clever and wrong. The suspicion stays on you like smoke.','你的推理很聪明，可惜错了。嫌疑像烟一样一直笼在你身上。'),c:'muted',fx:{merit:-4,happy:-3}}]},
  {l:T('Leave before they decide','不等裁决，先走为上'),out:[{t:T('You go down the mountain at night. To everyone who stayed, running away proves everything.','你连夜下山。在留下的人眼里，逃走就是认罪。'),c:'bad',fx:{align:-4,fame:-3,f:s=>{if(s.sect)leaveSect(s)}}}]}]});

I({id:'dk_rt_saintess',age:[16,35],once:1,w:.8,when:s=>dkRt(s)&&!spouseOf(s),ctx:s=>{const c=scene();c.npc=npc(s,{sex:s.gender==='m'?'f':'m',age:s.age+rint(-3,3)});return c},
 text:c=>T(`In a bamboo grove behind the town, someone is playing a qin so well the birds have stopped to listen. ${c.npc.en} looks up. You know that face: the Crimson Sky Cult’s honoured ${c.npc.sex==='f'?'Saintess':'Young Master'}.`,`镇后的竹林里，有人在抚琴，弹得连鸟都停下来听。${c.npc.zh}抬起头。这张脸你认得——赤霄教的${c.npc.sex==='f'?'圣女':'少主'}。`),
 opts:[{l:T('Sit and listen','坐下来听'),out:[{w:2,t:T('You come back the next night, and the next. Your sect must never know. You are in love with a "demon".','第二晚你又来了，第三晚也来了。师门绝不能知道。你爱上了一个"魔头"。'),c:'gold',fx:{meet:'lover',bond:65,happy:8,align:-3,flag:'dk_rt_love'}},{w:1,t:T('The music teaches you how to breathe. Then the player is gone, and you never see them again.','琴声教会了你如何吐纳。后来那人走了，你再也没见过。'),c:'good',fx:{qi:5,happy:3}}]},
  {l:T('Report it to your sect','禀告师门'),out:[{t:T('By the time the elders arrive, there is only a broken qin string on the ground. You keep it. You don’t know why.','长老们赶到时，地上只剩一根断了的琴弦。你把它收了起来，自己也说不清为什么。'),c:'muted',fx:{merit:3}}]},
  {l:T('Draw your sword','拔剑'),out:[{t:T('The music stops. "How dull," says the cultist, and is gone between one bamboo stalk and the next.','琴声停了。"真没意思。"那人说着，在两根竹子之间就不见了。'),c:'muted',fx:{align:1}}]}]});

I({id:'dk_rt_secret',age:[18,70],cd:15,tags:DKC,when:s=>dkRt(s)&&s.rank>=1,ctx:s=>{const c=scene();c.npc=npc(s,{occ:23,age:rint(35,50),lv:PW(1.0,6)(s)});return c},
 text:c=>T(`A Persian merchant, ${c.npc.en}, offers you five hundred taels and "a pill that doubles inner power" for a map of your sect’s mountain paths. You notice the crimson token on ${c.npc.his} belt.`,`波斯商人${c.npc.zh}出五百两银子，外加"一颗能让内力倍增的丹药"，要换你门派的山道图。你瞥见${c.npc.ta}腰间挂着一块赤霄令。`),
 opts:[{l:T('Sell the map','卖图'),out:[{w:2,t:T('You take the silver and the pill. The pill works. The raid comes three months later, and two of your juniors die in it.','你收了银子和药。药是真的。三个月后夜袭来了，两个师弟死在那一夜。'),c:'bad',fx:{money:500,qi:8,align:-15,merit:-5,happy:-8}},{w:1,t:T('The sect’s spymaster was watching the merchant. You are expelled in front of the whole mountain.','门中管刺探的长老一直盯着那商人。你被当着全山的面逐出了师门。'),c:'bad',fx:{money:500,align:-15,fame:-5,f:s=>{if(s.sect)leaveSect(s)}}}]},
  {l:T('Report the offer','禀报师门'),out:[{t:T('The elders set a trap with a false map. The raiders get lost for three days in a bog. You are commended.','长老们拿一张假图设了个局。夜袭的人在沼泽里迷了三天路。你受到了嘉奖。'),c:'good',fx:{merit:7,align:3}}]},
  {l:T('Seize the merchant','当场拿下'),fight:FG((s,c)=>c.npc.lv,'injury',T('The crimson token','赤霄令'),T('a cult agent','魔教细作')),
   win:[{t:T('You bring the merchant in bound, token and all. The elders look at you differently now.','你把那商人连人带令牌捆了回来。长老们看你的眼神从此不一样了。'),c:'good',fx:{merit:8,fame:3,enemy:1}}],
   lose:[{t:T('The merchant escapes with a laugh and tells everyone you took the money.','商人大笑着逃了，还到处说你收了他的钱。'),c:'bad',fx:{merit:-3,fame:-2}}]}]});

I({id:'dk_rt_music',age:[30,75],once:1,w:.7,when:s=>dkRt(s)&&s.smarts>=35,ctx:s=>{const c=scene();c.npc=npc(s,{occ:19,age:rint(55,70)});return c},
 text:c=>T(`For years you have played music with an old man, ${c.npc.en}, in a pavilion by the river. Today your sect master tells you who he is: an elder of the Crimson Sky Cult. "Kill him, or be counted as one of them."`,`多年来你常和一位老者${c.npc.zh}在江边亭子里合奏。今天师父告诉你他是谁：赤霄教的长老。"杀了他，否则你就算他们一伙。"`),
 opts:[{l:T('Kill your friend','杀了朋友'),out:[{t:T('He sees it in your eyes and plays one last piece before you draw. You never play music again.','他从你眼里看出了来意，在你拔剑前弹完了最后一曲。你从此再没碰过乐器。'),c:'bad',fx:{merit:10,align:-6,happy:-12}}]},
  {l:T('Refuse, and wash your hands of the jianghu','拒绝，金盆洗手'),out:[{w:2,t:T('You hold the hand-washing ceremony in public. The sects come to forbid it; the old man comes to save you. You both live, and leave the jianghu together, and compose a piece called "Song of Two Who Understood".','你当众举行金盆洗手大典。各派来阻止，老者来救你。你们都活了下来，一同退出江湖，合谱了一曲《知音行》。'),c:'gold',fx:{align:5,happy:10,fame:6,meet:'sworn',bond:85,deed:T('Composed "Song of Two Who Understood" with a friend from the other side','与正邪之外的知己合谱《知音行》'),f:s=>{if(s.sect)leaveSect(s)}}},{w:1,t:T('The sects come to forbid it. Your friend dies covering your escape, and the music dies with him.','各派来阻止。老友为掩护你逃走死了，那支曲子也随他去了。'),c:'bad',fx:{align:5,happy:-12,hurt:[15,30],cause:T('the righteous sects','名门正派'),f:s=>{if(s.sect)leaveSect(s)}}}]},
  {l:T('Warn him and stay','报信，自己留下'),out:[{t:T('The pavilion is empty when your sect arrives. Your master looks at you for a long time and says nothing. Neither do you.','师门的人赶到时，亭子已经空了。师父盯着你看了很久，一言不发。你也没说话。'),c:'muted',fx:{align:4,merit:-6}}]}]});

/* ====================== wuxia legends: encounter-only arts ====================== */
(()=>{const add={
 wxdagger:{n:'One-Cut Dagger',cn:'一刀封喉',tier:3,sk:'anqi',rare:1},
 wximmortal:{n:'Sword from Beyond',cn:'天外一剑',tier:3,sk:'jianqi',rare:1},
 wxlingxi:{n:'Two-Finger Catch',cn:'双指夹锋',tier:2,sk:'dianxue',rare:1},
 wxyiyang:{n:'Pure Yang Finger',cn:'纯阳指',tier:3,sk:'dianxue',rare:1},
 wxtoad:{n:'Crouching Toad Art',cn:'伏蟾功',tier:3,sk:'longzhang',rare:1},
 wxseven:{n:'Mutual Ruin Fist',cn:'玉石俱焚拳',tier:2,sk:'neishang',rare:1},
 wxcrescent:{n:'New Moon Saber',cn:'新月刀',tier:3,sk:'kuaijian',rare:1},
 wxsoul:{n:'Soul-Fogging Art',cn:'迷魂术',tier:2,sk:'shehun',rare:1},
 wxgoldbell:{n:'Golden Bell Cover',cn:'金钟罩',tier:2,sk:'jinzhong',rare:1},
 wxtaixuan:{n:'Stone Wall Script',cn:'石壁玄文',tier:3,sk:'jianqi',rare:1},
 wxshenxing:{n:'Hundred-Shift Steps',cn:'百变身法',tier:2,sk:'lingbo',rare:1},
 wxdarkiron:{n:'Heavy Sword Forms',cn:'重剑式',tier:3,sk:'pojia',rare:1},
 wxstarshift:{n:'Turnabout Art',cn:'反手乾坤',tier:3,sk:'fanzhen',rare:1},
 wxcarefree:{n:'Carefree Roaming Fist',cn:'逍遥游',tier:2,sk:'lianhuan',rare:1}};
 const have=new Set(Object.values(ARTS).map(a=>a.cn));for(const k in add)if(!ARTS[k]&&!have.has(add[k].cn))ARTS[k]=add[k]})();
/* teach an art only if it exists (another file may have claimed the name) */
const wxArt=k=>ARTS[k]?k:null;
const wxHas=(s,k)=>!!ARTS[k]&&s.arts.some(a=>a.cn===ARTS[k].cn);
const WXW=['wander'];

I({id:'wx_cliff',age:[14,55],once:1,w:.6,tags:WXW,
 text:()=>T('Mist hides the edge of the cliff path. One wrong step, and you fall a very long way. Pine branches break your fall, then your ribs. You wake in a hidden valley no map has ever shown.','雾气遮住了栈道的边缘。一脚踩空，你坠了很久很久。松枝挡住了你，也折断了你的肋骨。你在一处从没上过地图的幽谷里醒来。'),
 opts:[{l:T('Follow the limping white ape','跟着那只瘸腿的白猿'),out:[{w:s=>s.t.luck*.25,t:T('The ape has a lump in its belly. You cut it open, heal the wound with herbs, and find an oilcloth packet: the Great Sun Manual. You spend four years in the valley.','白猿肚子里有个硬块。你剖开取出，又用草药替它缝好伤口——是一个油布包，里面是《大日真经》。你在谷里一待就是四年。'),c:'gold',fx:{hurt:[10,20],cause:T('a fall from a cliff','坠崖'),art:'ninesun',qi:10,deed:T('Found the Great Sun Manual in the belly of a white ape','于白猿腹中得《大日真经》')}},
   {w:2,t:T('The ape leads you to a grove of red fruit. You eat until you can walk, and climb out stronger than you fell in.','白猿把你领到一片红果林。你吃到能走路了，爬出去时比掉下来时还壮实。'),c:'good',fx:{hurt:[10,20],cause:T('a fall from a cliff','坠崖'),maxHealth:4,qi:5}},
   {w:1,t:T('The ape steals your boots and climbs out of the valley. You follow it, barefoot, for three weeks.','白猿偷走了你的靴子，爬出了山谷。你光着脚跟着它走了三个星期。'),c:'muted',fx:{hurt:[12,22],cause:T('a fall from a cliff','坠崖'),happy:-3}}]},
  {l:T('Rest, and live off the valley','安心养伤，靠山吃山'),out:[{w:2,t:T('A year of silence, spring water and breathing. You leave with your bones knitted and your mind still.','一年的寂静、泉水和吐纳。你走时骨头长好了，心也静了。'),c:'good',fx:{hurt:[10,20],cause:T('a fall from a cliff','坠崖'),qi:8,heal:20}},
   {w:1,t:T('On a cave wall someone has carved sword moves. They make no sense until the last week, when they make all the sense in the world.','山洞石壁上刻着剑招。直到最后一个星期，你才忽然全看懂了。'),c:'gold',fx:{hurt:[10,20],cause:T('a fall from a cliff','坠崖'),skill:6}}]},
  {l:T('Climb straight back out','立刻往上爬'),out:[{w:s=>s.t.root,t:T('You climb for two days on broken ribs. At the top you lie in the grass and laugh at the sky.','你带着断肋爬了两天。到了崖顶，你躺在草地上，对着天哈哈大笑。'),c:'good',fx:{hurt:[15,25],cause:T('a fall from a cliff','坠崖'),talent:{root:1}}},{w:3,t:T('Halfway up, you fall again.','爬到一半，你又摔了下去。'),c:'bad',fx:{hurt:[18,32],cause:T('a fall from a cliff','坠崖')}}]}]});

I({id:'wx_eagle',age:[18,55],once:1,w:.5,when:s=>power(s)>=60&&s.t.root>=5,
 text:()=>T('A huge, ugly eagle, taller than a man, blocks the mountain path. It bows its head to you, almost politely, and walks off into the forest, looking back.','一只比人还高的丑陋大雕拦在山路上。它朝你低了低头，几乎称得上彬彬有礼，然后回头望着你，走进了林子。'),
 opts:[{l:T('Follow it','跟上去'),out:[{w:3,t:T('It leads you to a grave: "A sword is buried here, not a man." Three swords lie there, and a heavy black one. The eagle wants you to train, in the flood, with the heavy sword, for as long as it takes.','它把你带到一座坟前："此处葬剑，不葬人。"墓旁三柄剑，还有一柄黝黑的重剑。大雕要你在山洪里用这柄重剑练，练到成为止。'),c:'gold',fx:{flag:'wx_eagle'},next:'wx_eagle2'}]},
  {l:T('Fight it','和它较量'),fight:FG(PW(1.1,10),'injury',T('The giant eagle','巨雕'),T('a giant eagle','巨雕'),()=>T('the giant eagle','巨雕'),true),
   win:[{t:T('You fight it to a standstill. It looks at you with something like approval, and leaves you a single feather.','你和它斗了个平手。它带着几分赞许看了你一眼，留下一根羽毛走了。'),c:'good',fx:{skill:3,fame:2}}],
   lose:[{t:T('Its wings knock you flat. It stands over you a moment, disappointed, and is gone.','它一翅膀把你扇倒在地，站在你身旁看了一会儿，失望地走了。'),c:'bad'}]},
  {l:T('Back away slowly','慢慢退开'),out:[{t:T('It watches you go. You wonder about it for the rest of your life.','它看着你离开。此后一生，你都会时不时想起它。'),c:'muted'}]}]});
I({id:'wx_eagle2',sys:1,text:()=>T('The flood roars down the gorge. The eagle waits.','山洪在峡谷里咆哮。大雕在等你。'),
 opts:[{l:T('Train in the flood with the heavy sword','在山洪中练重剑'),sub:T('Costly and dangerous. Great reward if your bones can bear it.','代价高、凶险大。根骨撑得住，所获无穷。'),out:[{w:s=>s.t.root-3,t:T('Season after season the eagle beats you into the torrent until you can hold the heavy sword still against the whole river. "The heavier the sword, the lighter the hand."','一季又一季，大雕把你一次次扇进激流，直到你能举着重剑在整条大河里纹丝不动。"剑越重，手越要轻。"'),c:'gold',fx:{hurt:[15,30],cause:T('training in a mountain flood','山洪练剑'),art:'wxdarkiron',item:'heavysword',deed:T('Trained with the Sword Demon’s eagle and learned the Heavy Sword Forms','随巨雕于山洪中练成重剑式')}},
   {w:3,t:T('The river wins. The eagle drags you out, half drowned, and lets you go with a look of pity.','大河赢了。大雕把半死的你拖上岸，带着怜悯放你走了。'),c:'bad',fx:{hurt:[20,35],cause:T('training in a mountain flood','山洪练剑'),skill:4}}]},
  {l:T('Take only the wooden sword, and leave','只取那柄木剑离去'),out:[{t:T('"In the end, it does not matter what you hold." You understand a little of it. Enough to be dangerous.','"到了最后，手里拿什么都一样。"你懂了一点。一点就够可怕了。'),c:'good',fx:{qi:8,talent:{wit:1}}}]},
  {l:T('Bow to the grave and leave everything','向剑冢一拜，一物不取'),out:[{t:T('The eagle nods. You walk away lighter than you came.','大雕点了点头。你来时满怀心事，走时一身轻松。'),c:'good',fx:{align:5,talent:{heart:1}}}]}]});

I({id:'wx_swordtomb',only:1,ctx:s=>{const c=scene();c.npc=npc(s,{age:rint(25,45),lv:PW(1.0,6)(s)});return c},
 text:()=>T('The rumour was true. In a valley of red stone there are four sword graves, each with a line carved above it: the sharp sword, the soft sword, the heavy sword, the wooden sword. Other treasure hunters are already digging.','传言是真的。红石谷里有四座剑冢，各刻一行字：利剑、软剑、重剑、木剑。已经有别的寻宝人在挖了。'),
 opts:[{l:T('Dig at the sharp sword','挖利剑冢'),out:[{w:1,t:T('A cold iron saber, still sharp after a hundred years. It cuts the shovel in half.','一柄寒铁刀，百年不锈，一挥就把铁锹削成了两截。'),c:'gold',fx:{item:'coldsaber'}},{w:2,t:T('Only rust and a note: "When I was young I thought sharpness was everything." You learn something about pride.','只有铁锈和一张字条："年少时，我以为锋利就是一切。"你对"骄傲"二字多了些体会。'),c:'muted',fx:{skill:2}}]},
  {l:T('Dig at the wooden sword','挖木剑冢'),out:[{w:s=>s.t.wit,t:T('Only a rotten stick. You hold it and suddenly see that a sword is just a way of paying attention.','只有一根朽木。你握着它，忽然明白了：剑，不过是专注的一种方式。'),c:'gold',fx:{qi:10,skill:4,talent:{wit:1}}},{w:5,t:T('A rotten stick. You throw it away. Somewhere a dead swordsman sighs.','一根朽木。你随手扔了。某处，一个死去的剑客叹了口气。'),c:'muted',fx:{skill:1}}]},
  {l:T('Drive the other hunters off first','先把别的寻宝人赶走'),fight:FG((s,c)=>c.npc.lv,'injury',T('The sword tomb','剑冢'),T('a rival treasure hunter','争宝之人')),
   win:[{t:T('With the valley to yourself you dig at all four graves. Heavy iron, a soft sword in a belt, and a saber that sings.','山谷归你一个人了。四座剑冢你都挖了：一块沉铁，一柄藏在腰带里的软剑，还有一柄会鸣的刀。'),c:'gold',fx:{item:'steelsword',money:200,fame:3}}],
   lose:[{t:T('They bury you up to your neck in the valley and dig in peace. You are freed the next day by a goat.','他们把你埋到只剩脑袋，安安心心地挖宝去了。第二天一只山羊把你刨了出来。'),c:'bad',fx:{happy:-4}}]}]});

I({id:'wx_chess',age:[20,80],once:1,w:.5,ctx:s=>{const c=scene();c.npc=npc(s,{occ:19,age:rint(80,95)});return c},
 text:c=>T(`On a mountain top, a hundred masters sit around a stone board. An old man hidden behind a wall has set a puzzle no one has solved in thirty years: the Unfinished Game. Somehow, it is your turn.`,`山顶上，上百位高手围着一副石棋盘。一位藏在石壁后的老人摆下了三十年无人能解的"千古残局"。不知怎的，轮到你了。`),
 opts:[{l:T('Play to win','用心求胜'),out:[{w:s=>s.smarts/25,t:T('You play brilliantly, and lose brilliantly. The old man says, "Better than most." Your mind is sharper for it.','你下得精彩，输得也精彩。老人说："胜过大多数人了。"你的心思从此更敏锐。'),c:'good',fx:{smarts:6,talent:{wit:1}}},{w:3,t:T('Every path ends in death. You see your whole life in the stones and cough up blood.','每一条路都通向死局。你在棋子里看见了自己的一生，一口血喷了出来。'),c:'bad',fx:{hurt:[8,18],cause:T('a chess puzzle','千古残局'),smarts:2}}]},
  {l:T('Shut your eyes and kill your own stones','闭眼一子，自杀一大片'),out:[{w:s=>1+s.t.luck*.15,t:T('It is the stupidest move anyone has ever made, and it breaks the puzzle open. The old man laughs, pulls you behind the wall, and pours seventy years of inner power into you. "Now go and find the others," he says, and dies smiling.','这是有史以来最蠢的一步棋，棋局却豁然开朗。老人大笑，把你拉进石壁后，将七十年功力尽数灌入你体内。"去吧，去找他们。"说完，他含笑而逝。'),c:'gold',fx:{qi:30,skill:6,talent:{root:1},deed:T('Broke the Unfinished Game','破解千古残局')}},{w:3,t:T('The masters groan. The old man says nothing. You have lost in the most embarrassing way possible.','高手们一片哀叹。老人一言不发。你输得要多难看有多难看。'),c:'muted',fx:{happy:-3}}]},
  {l:T('Decline to play','推辞不下'),out:[{t:T('You watch others try. You learn more from their failures than they do.','你看着别人一个个去试，从他们的失败里学到的比他们自己还多。'),c:'muted',fx:{smarts:2}}]}]});

I({id:'wx_music',age:[16,75],once:1,w:.6,when:s=>s.smarts>=40,ctx:s=>{const c=scene();c.npc=npc(s,{occ:19,age:rint(50,70)});return c},
 text:c=>T(`In a bamboo hut, a recluse, ${c.npc.en}, plays half of a piece on the qin and stops. "The flute part died with my friend. Can you play it?"`,`竹屋里，隐士${c.npc.zh}在琴上弹了半支曲子，停了下来。"箫的那一半，随我的老友去了。你会吹吗？"`),
 opts:[{l:T('Take up the flute','拿起竹箫'),out:[{w:s=>s.smarts/20+s.t.heart/3,t:T('You do not know the piece, and then you do. Qin and flute climb together until the bamboo shakes. He weeps. Your inner energy settles like a lake.','你本不会这支曲子，吹着吹着就会了。琴箫相和，越拔越高，竹林都在摇。他哭了。你的真气静得像一汪湖水。'),c:'gold',fx:{qi:10,talent:{heart:1},meet:'friend',bond:80}},{w:2,t:T('You squeak. He winces. Then he laughs for the first time in years.','你吹出一声怪响。他皱了皱眉，接着笑了——这是他多年来第一次笑。'),c:'good',fx:{happy:5,meet:'acq',bond:60}}]},
  {l:T('Just listen','静静地听'),out:[{t:T('He plays the qin part alone, twice. The silence where the flute should be is the saddest thing you have ever heard.','他独自把琴的部分弹了两遍。本该是箫声的地方空着，那是你听过最悲伤的声音。'),c:'muted',fx:{qi:4,happy:-1}}]},
  {l:T('Ask for the score','讨要曲谱'),out:[{t:T('He hands it over. "It is called Song of Two Who Understood. Keep it out of the hands of anyone who would use it." You sell it. You regret it.','他把谱子给了你。"它叫《知音行》。别让那些会利用它的人拿去。"你把它卖了。你后悔了。'),c:'muted',fx:{money:80,align:-3}}]}]});

I({id:'wx_seven',age:[16,60],once:1,w:.6,tags:WXW,ctx:s=>{const c=scene();c.npc=npc(s,{occ:19,age:rint(60,75)});return c},
 text:c=>T(`In a cave sheltering from a storm, you find a dying man, ${c.npc.en}. He is poisoned and knows it. "Water," he says. "And then I will give you something terrible."`,`你躲雨钻进一个山洞，里面有个快死的人${c.npc.zh}。他中了毒，自己心里清楚。"水，"他说，"然后我送你一样可怕的东西。"`),
 opts:[{l:T('Give him water, and listen','给他水，听他说'),out:[{w:s=>s.qi>=20?3:1,t:T('He teaches you the Mutual Ruin Fist. "Every blow wounds your own organs before your enemy’s. Use it seven times in your life, no more." He dies before dawn.','他把玉石俱焚拳传给了你。"每一拳先伤己，后伤人。一生之中，用不过七次。"天亮前他死了。'),c:'gold',fx:{art:'wxseven',maxHealth:-4,align:2}},{w:2,t:T('He tries to teach you, but your qi is too thin. The first form tears something in your chest. He dies apologising.','他想教你，可你内力太浅，第一式就震伤了胸口。他是一边道歉一边咽气的。'),c:'bad',fx:{hurt:[10,20],cause:T('the Mutual Ruin Fist','玉石俱焚拳'),align:2}}]},
  {l:T('Try to cure the poison','设法解毒'),if:s=>s.smarts>=50,out:[{w:1,t:T('Three herbs, a hot stone, and a week of nursing. He lives, and takes you as his student out of sheer surprise.','三味草药，一块热石，一个星期的照料。他活了过来，惊讶之下收了你做徒弟。'),c:'gold',fx:{meet:'master',bond:75,align:6,skill:4}},{w:2,t:T('You try everything. He dies at peace, at least, with someone holding his hand.','你试遍了所有法子。至少他走时很安详，身边有人握着他的手。'),c:'muted',fx:{align:4,smarts:2}}]},
  {l:T('Take his purse and leave','拿了钱袋就走'),out:[{t:T('Forty taels and a curse that follows you out into the rain.','四十两银子，外加一声追着你进了雨里的诅咒。'),c:'bad',fx:{money:40,align:-6,happy:-2}}]}]});

I({id:'wx_toad',age:[14,45],once:1,w:.5,tags:WXW,ctx:s=>{const c=scene();c.npc=npc(s,{occ:19,age:rint(60,70),lv:PW(1.3,12)(s)});return c},
 text:()=>T('A wild-haired old man is walking on his hands down the road. He stops, upside down, and grabs your ankle. "Who am I? Tell me who I am!"','一个披头散发的老头用双手倒立着走在路上。他倒着停下来，一把抓住你的脚踝。"我是谁？告诉我，我是谁！"'),
 opts:[{l:T('"You are my father!"','"你是我爹！"'),out:[{w:s=>s.t.luck*.25,t:T('He weeps with joy, calls you his child, and for a month teaches you the strangest art in the world: you crouch like a toad and croak, and then the ground shakes. The Crouching Toad Art of the old Venom King.','他喜极而泣，认你做了孩儿，教了你一个月天下最古怪的武功：蹲得像只蛤蟆，咕咕一叫，地面就跟着震。这正是当年老毒王的伏蟾功。'),c:'gold',fx:{art:'wxtoad',happy:5,deed:T('Was taught the Crouching Toad Art by the mad old Venom King','得疯癫的老毒王亲传伏蟾功')}},{w:3,t:T('He thinks about it, then slaps you. "I have no children. Liar." He hops away.','他想了想，给了你一巴掌。"我没有儿子。骗子。"他蹦着走了。'),c:'muted',fx:{hurt:[3,8],cause:T('a madman’s slap','疯子的巴掌')}}]},
  {l:T('"You are the old Venom King."','"你是当年的老毒王。"'),fight:FG((s,c)=>c.npc.lv,'injury',T('The Venom King','老毒王'),T('the mad Venom King','疯癫的老毒王'),()=>T('the mad old man','疯老头')),
   win:[{t:T('You survive him, barely. He sits in the road and cries, "Venom King, Venom King," until he forgets again.','你勉强顶住了他。他坐在路中间哭着念"老毒王，老毒王"，直到又忘了。'),c:'good',fx:{fame:6,skill:3}}],
   lose:[{t:T('Hearing his own name sends him into a rage. You wake up in a ditch with toad prints on your chest.','听到自己的名字，他发了狂。你在水沟里醒来，胸口印着个蛤蟆样的掌印。'),c:'bad',fx:{hurt:[6,14],cause:T('the Crouching Toad Art','伏蟾功')}}]},
  {l:T('"You are you."','"你就是你。"'),out:[{t:T('He lets go of your ankle and thinks about this upside down for a long time. You leave him there, thinking.','他松开了你的脚踝，倒立着想了很久。你走了，他还在想。'),c:'muted',fx:{qi:3,smarts:1}}]}]});

I({id:'wx_yiyang',age:[16,60],once:1,w:.5,when:s=>s.align>=20,ctx:s=>{const c=scene();c.npc=npc(s,{occ:20,age:rint(8,12)});return c},
 text:c=>T(`A girl, ${c.npc.en}, has been struck by a palm that is killing her slowly. Only the old monk on the mountain, who was a prince before he shaved his head, can save her, and four of his disciples guard the way: a fisherman, a woodcutter, a farmer and a scholar.`,`小姑娘${c.npc.zh}中了一记慢慢要人命的掌力。只有山上那位出家前做过王爷的老和尚能救她，而路上守着他的四大弟子：渔、樵、耕、读。`),
 opts:[{l:T('Carry her up, and pass the four tests','背她上山，闯渔樵耕读四关'),out:[{w:s=>s.smarts/20+s.t.heart/3,t:T('You carry the fisherman’s boat up a waterfall, sing with the woodcutter, hold up the farmer’s boulder and answer the scholar’s riddles. The monk spends half his power to save the girl, and, seeing your heart, teaches you the Pure Yang Finger.','你替渔人背船上瀑布，同樵子对歌，替农夫扛住巨石，又答出了书生的谜题。大师耗去一半功力救活了小姑娘，见你心地纯良，传了你纯阳指。'),c:'gold',fx:{art:'wxyiyang',align:8,fame:4,deed:T('Carried a dying child to the monk who had been a prince','负垂危孩童上山求那位王爷和尚')}},{w:2,t:T('You fail the scholar’s riddle, but the monk comes down himself, sighing, to save the girl. "Your feet passed the test," he says. "Your head can try again."','你没答上书生的谜，可大师叹着气亲自下山救了小姑娘。"你的脚过了关，"他说，"你的脑子还可以再试。"'),c:'good',fx:{align:6,qi:5,smarts:2}}]},
  {l:T('Fight your way past the disciples','硬闯上去'),fight:FG(PW(1.1,8),'light',T('The four disciples','渔樵耕读'),T('the monk’s four disciples','王爷和尚的四大弟子'),()=>T('the four disciples','渔樵耕读四弟子')),
   win:[{t:T('You force the way. The monk saves the girl, and then looks at you sadly. "So much strength, so little patience." He gives you nothing else.','你闯了上去。大师救了小姑娘，又怅然看着你。"力气这么大，耐心这么少。"别的什么也没给你。'),c:'muted',fx:{align:3,fame:2}}],
   lose:[{t:T('The farmer drops you into a paddy. The scholar, ashamed for you, carries the girl up himself.','农夫把你扔进了水田。书生替你害臊，自己把小姑娘背了上去。'),c:'bad',fx:{align:2}}]},
  {l:T('Find a doctor in town instead','去镇上找大夫'),out:[{t:T('The doctor shakes his head. The girl lives a year. It is a good year; you see to that.','大夫摇了摇头。小姑娘又活了一年。那是很好的一年，你尽力让它好。'),c:'muted',fx:{align:3,happy:-6}}]}]});

I({id:'wx_dagger',age:[18,60],once:1,w:.5,ctx:s=>{const c=scene();c.npc=npc(s,{occ:13,sex:'m',age:rint(38,45)});return c},
 text:c=>T(`In a snowbound inn, a pale man who coughs blood is whittling a flute with a small knife. Everyone gives him room. They whisper that his knife has never needed a second throw.`,`大雪封路的客栈里，一个咳着血的苍白男子正用一把小刀削一支竹笛。人人都离他远远的，低声说：他的飞刀，从没出过第二把。`),
 opts:[{l:T('Sit with him and drink','坐下陪他喝酒'),out:[{w:s=>(s.t.heart+s.t.wit)*.12,t:T('You drink through three nights of snow. On the fourth he hands you the little knife. "It is not the hand that throws it," he says. "It is the reason." You understand.','大雪下了三夜，你陪他喝了三夜。第四天他把那把小刀递给你。"飞刀不在手上，"他说，"在心里。"你懂了。'),c:'gold',fx:{art:'wxdagger',meet:'friend',bond:80,deed:T('Drank three snowbound nights with the coughing knife-thrower','与咳血的飞刀客雪夜对饮三宿')}},{w:3,t:T('He drinks more than you can believe and speaks very little. When the snow stops he leaves you the flute. You keep it all your life.','他的酒量大得叫人不敢信，话却很少。雪停时，他把那支竹笛留给了你。你珍藏了一辈子。'),c:'good',fx:{happy:6,meet:'acq',bond:65}}]},
  {l:T('Ask to see the dagger','请他亮一亮飞刀'),out:[{t:T('He looks at you a long moment. "I hope you never see it." He coughs, and goes back to carving. Somehow your skill grows from the look alone.','他看了你很久。"但愿你永远看不见它。"他咳了几声，接着刻他的木头。不知怎的，光是那一眼就让你长进了。'),c:'good',fx:{skill:3}}]},
  {l:T('Challenge him','向他挑战'),out:[{t:T('You stand. Something cold touches your throat. You never saw him move. "Sit down," he says gently. "It is snowing." You sit.','你刚站起来，喉咙上就多了一点凉意。你根本没看见他出手。"坐下吧，"他温和地说，"外面在下雪。"你坐下了。'),c:'muted',fx:{fame:1,happy:-2}}]}]});

I({id:'wx_roof',age:[18,70],once:1,w:.5,when:s=>power(s)>=80||s.fame>=40,
 text:()=>T('"On the night of the full moon, on top of the Bell Tower." The Lord of the Southern Isle and the Sword Saint of the North will duel across the city roofs, and you are among the few who got close enough to watch.','"月圆之夜，钟楼之巅。"南海岛主与北地剑圣要在城中屋脊上决战，你是少数挤得到近处观战的人之一。'),
 opts:[{l:T('Watch the Sword from Beyond','凝神看那一式"天外一剑"'),out:[{w:s=>Math.max(0,s.t.wit-5),t:T('One sword falls from the moon. You see it, and in seeing it, you have it. The duel ends, and something in you has begun.','一剑自月中而来。你看见了，看见即是得到。决战结束了，你身上却有什么开始了。'),c:'gold',fx:{art:'wximmortal',deed:T('Saw the duel on top of the Bell Tower','亲见钟楼之巅一战')}},{w:4,t:T('You see a flash and then one man standing. That is enough to keep you awake for a year.','你只看见一道光，然后就只剩一个人站着。这已经够你一年睡不着觉了。'),c:'good',fx:{skill:4,qi:3}}]},
  {l:T('Bet on the duel','押注'),cost:50,out:[{w:1,t:T('You bet on the Sword Saint. You win, and feel a little ashamed of it.','你押了剑圣。你赢了，却有些惭愧。'),c:'good',fx:{money:150}},{w:1,t:T('You bet on the Island Lord. He is the better swordsman, and he loses, for reasons that have nothing to do with swords.','你押了岛主。他剑法更高，却输了——原因与剑毫无关系。'),c:'muted',fx:{smarts:2}}]},
  {l:T('Watch the crowd instead','去看人群'),out:[{t:T('While everyone looks at the roof, you see a eunuch slip through a side door with a forged token. You tell the palace guard. Nobody ever thanks you.','人人都盯着屋顶时，你看见一个太监拿着假令牌溜进了侧门。你告诉了禁卫。从没人谢过你。'),c:'good',fx:{align:4,smarts:2}}]}]});

I({id:'wx_crescent',age:[16,45],once:1,w:.45,when:s=>s.happy<55,ctx:s=>{const c=scene();c.npc=npc(s,{sex:s.gender==='m'?'f':'m',age:s.age+rint(-2,2)});return c},
 text:c=>T(`Beaten and humiliated, you sit by a lake under the full moon, thinking about drowning. Someone in green, ${c.npc.en}, steps out of the reeds holding a curved saber like a slice of moon. On the blade: "Life is a dream; pour one cup for the moon on the river."`,`你受尽羞辱，坐在月下湖边，想着要不要投水。一个绿衣人${c.npc.zh}从芦苇里走出来，手里一柄弯刀如一弯新月。刀上刻着："人生如梦，一尊还酹江月。"`),
 opts:[{l:T('Take the saber','接过弯刀'),out:[{w:2,t:T('The New Moon Saber. You practise until the moon sets, and every stroke is a curve that nobody can see coming. The one in green stays, and you are never quite sure whether they are human.','新月刀。你练到月落，每一刀都弯得叫人看不出来路。绿衣人留了下来，你始终说不清那是不是人。'),c:'gold',fx:{art:'wxcrescent',meet:'lover',bond:70,happy:10,deed:T('Received the New Moon Saber by a moonlit lake','月下湖畔得新月刀')}},{w:1,t:T('The saber is too heavy for your sorrow. In the morning you are alone with a fox’s footprints and a little more courage.','这刀太重，你满腹心事拿不动。天亮时，你身边只剩一串狐狸脚印，心里多了几分勇气。'),c:'good',fx:{happy:8,skill:2}}]},
  {l:T('Refuse','拒绝'),out:[{t:T('"Then live with your own blade," they say, and the reeds close. You go home. You do not drown.','"那就靠你自己的刀活下去吧。"芦苇合上了。你回了家，没有投水。'),c:'muted',fx:{happy:4}}]}]});

I({id:'wx_soul',age:[18,60],once:1,w:.45,tags:WXW,ctx:s=>{const c=scene();c.npc=npc(s,{occ:27,sex:'f',age:rint(40,50),lv:PW(1.1,8)(s)});return c},
 text:c=>T(`At midnight, a blind woman with long iron nails, ${c.npc.en}, holds out a page torn from a manual. "Read it to me. If you read it wrong, I will know."`,`三更半夜，一个指甲又长又硬的盲眼女人${c.npc.zh}递过来一页撕下的秘籍。"念给我听。念错一个字，我就知道。"`),
 opts:[{l:T('Read it truthfully','照实念'),out:[{w:s=>s.t.wit*.3,t:T('It is the Soul-Fogging Art, torn from some forbidden manual. By the time you finish, it is written in your head too. She thanks you, and you run before she remembers that witnesses talk.','那是从某本禁书上撕下的迷魂术。念完时，它也印进了你的脑子。她谢了你，你趁她还没想起"知情者会多嘴"就跑了。'),c:'gold',fx:{art:'wxsoul',align:-3}},{w:3,t:T('Halfway through she decides you have heard enough. Her nails go for your throat; you escape with three bloody lines across your neck.','念到一半，她觉得你听得够多了，十指直取你的喉咙。你逃了出来，脖子上多了三道血痕。'),c:'bad',fx:{hurt:[10,22],cause:T('the White Bone Claw','白骨爪')}}]},
  {l:T('Read it wrong, on purpose','故意念错'),fight:FG((s,c)=>c.npc.lv,'injury',T('The blind witch','盲眼妖妇'),T('the White Bone Claw','白骨爪')),
   win:[{t:T('She knows. She attacks. You win, somehow, and burn the page so nobody else learns that art.','她听出来了，扑了上来。你居然赢了，把那页纸烧了，免得再有人学去。'),c:'good',fx:{align:6,fame:3}}],
   lose:[{t:T('Her nails leave five holes in your shoulder that never quite stop aching.','她的指甲在你肩上留下五个窟窿，此后一直隐隐作痛。'),c:'bad',fx:{maxHealth:-2}}]},
  {l:T('Refuse','不念'),out:[{t:T('"Coward," she says, and listens to you walk away. You feel her listening for a long time.','"胆小鬼。"她说，侧耳听着你走远。你觉得她听了很久很久。'),c:'muted'}]}]});

I({id:'wx_goldbell',age:[14,50],once:1,w:.5,when:s=>s.t.root>=6,ctx:s=>{const c=scene();c.npc=npc(s,{occ:4,age:rint(70,85)});return c},
 text:c=>T(`An old monk, ${c.npc.en}, sits under the bronze bell of a ruined temple. "Strike me with all your strength. Every day for a hundred days. Then it will be my turn."`,`破庙的铜钟下坐着一位老僧${c.npc.zh}。"用你全身的力气打我。每天一次，打一百天。然后轮到我。"`),
 opts:[{l:T('Agree','答应'),sub:T('A hundred days of beating. A sacrifice of the body.','挨一百天的打。以身相殉。'),out:[{w:s=>s.t.root-4,t:T('He never flinches. Then it is your turn, and every blow rings through you like the bell. On the hundredth day, nothing hurts. Golden Bell Cover.','他从未皱过眉头。然后轮到你了，每一掌都像钟声一样在你身上回荡。第一百天，你什么都感觉不到了。金钟罩，成了。'),c:'gold',fx:{art:'wxgoldbell',hurt:[15,30],cause:T('a hundred days of blows','百日击打'),soft:1,maxHealth:3}},{w:3,t:T('On the fortieth day you cannot get up. The monk carries you to the village and leaves you a bowl of rice and a bruise for every day.','第四十天你爬不起来了。老僧把你背到村里，给你留了一碗饭，和每天一块的淤青。'),c:'bad',fx:{hurt:[20,35],cause:T('a hundred days of blows','百日击打'),soft:1,skill:3}}]},
  {l:T('Ring the bell instead','改去敲那口钟'),out:[{t:T('The bell is enormous and very loud. The monk laughs. "Also a way," he says, and lets you sleep in the temple.','钟大得出奇，响得惊人。老僧笑了："也是一条路。"他留你在庙里睡了一晚。'),c:'muted',fx:{qi:3}}]},
  {l:T('Walk on','走开'),out:[{t:T('Behind you, the bell rings once, by itself.','身后，那口钟自己响了一声。'),c:'muted'}]}]});

I({id:'wx_taixuan',only:1,
 text:()=>T('A bronze token brought you to the Stone Wall Isle. In a cave, twenty-four stone walls are covered in an ancient poem and its thousands of commentaries. Masters who came thirty years ago are still here, arguing over them.','一块铜牌请帖把你带到了石壁岛。石洞里二十四面石壁，刻着一首古诗和成千上万条注解。三十年前上岛的高手们，至今还在这里争论不休。'),
 opts:[{l:T('Study the commentaries','细读注解'),out:[{w:s=>s.smarts/25,t:T('You read for a year and understand everything the commentators understood, which is not the art. You leave wiser and a little older.','你读了一年，把注解者们懂的都懂了——可那不是武功。你离开时更聪明了，也老了一些。'),c:'good',fx:{smarts:6,skill:4}},{w:1,t:T('You read for ten years. The island food is excellent. You leave old.','你读了十年。岛上的饭很好吃。你老了才离岛。'),c:'muted',fx:{smarts:8,lifespan:-2}}]},
  {l:T('Ignore the words, look only at the shapes','不看字，只看笔画形状'),out:[{w:s=>Math.max(.4,(100-s.smarts)/25),t:T('You barely read, so the strokes are just strokes: swords and veins and breath. They begin to move. The Stone Wall Script opens to you, as it may have to some unlettered visitor long ago.','你本就识字不多，那些笔画在你眼里只是笔画：是剑，是经脉，是呼吸。它们动了起来。《石壁玄文》向你敞开了，就像也许曾对某个不识字的来客那样。'),c:'gold',fx:{art:'wxtaixuan',qi:10,deed:T('Grasped the Stone Wall Script on the Stone Wall Isle','于石壁岛石壁悟得石壁玄文')}},{w:s=>s.smarts/30,t:T('You cannot stop reading the words. They are in the way. You leave with a headache.','你没办法不去看那些字，它们挡在路上。你带着头疼离开了。'),c:'muted',fx:{qi:3}}]},
  {l:T('Eat a meal and go home','吃顿饭就回家'),out:[{t:T('You are the only guest in thirty years to leave in the first week. The island masters find this very funny.','三十年来，你是头一个一周内就离岛的客人。岛主们觉得这事好笑极了。'),c:'muted',fx:{happy:3,fame:2}}]}]});

I({id:'wx_shenxing',age:[12,40],once:1,w:.5,tags:WXW,ctx:s=>{const c=scene();c.npc=npc(s,{occ:3,age:rint(45,55)});return c},
 text:c=>T(`You try to steal a bun from a one-armed nun, ${c.npc.en}. She catches you without turning round, holds you up by the collar and studies you. "You are terrible at running away. That will get you killed."`,`你想偷一个独臂尼姑${c.npc.zh}的馒头。她头都没回就把你拎了起来，打量着你。"你逃跑的本事太差了。迟早要送命。"`),
 opts:[{l:T('Beg her to teach you','求她教你'),out:[{w:s=>s.t.luck*.2+s.t.wit*.1,t:T('She teaches you to run, for a year, like a hare that has read the Art of War. "Hundred-Shift Steps. The only art you will ever really need."','她教了你一年怎么跑，跑得像一只读过兵法的兔子。"百变身法。你这辈子真正用得着的，也就这一门。"'),c:'gold',fx:{art:'wxshenxing',meet:'master',bond:60}},{w:2,t:T('She teaches you for a week, decides you are hopeless, and leaves you the bun.','她教了你一个星期，认定你没救了，把馒头留给了你。'),c:'good',fx:{skill:2}}]},
  {l:T('Run','跑'),out:[{t:T('You run. She walks. She arrives first. She gives you the bun out of pity.','你跑，她走。她先到。她可怜你，把馒头给了你。'),c:'muted',fx:{happy:2}}]},
  {l:T('Apologise and pay','道歉付钱'),out:[{t:T('"Polite. Boring." She takes the copper and is gone.','"有礼貌。没意思。"她收了铜钱就走了。'),c:'muted',fx:{align:1}}]}]});

I({id:'wx_starshift',age:[20,60],once:1,w:.4,when:s=>s.smarts>=55,ctx:s=>{const c=scene();c.npc=npc(s,{occ:12,sex:'f',age:rint(17,22)});return c},
 text:c=>T(`A maid of the Nangong family, ${c.npc.en}, rows you through the fog to Mirror Lake Manor to wait for her master. You are left alone, by mistake, in the Water Pavilion where the Nangong keep a copy of every sect’s secret manual.`,`南宫家的侍女${c.npc.zh}摇船载你穿过雾气，到镜湖山庄等她家公子。阴差阳错，你被一个人留在了水阁里——南宫家收藏天下各派秘籍的地方。`),
 opts:[{l:T('Read the Nangong’s own art','只读南宫家的绝学'),out:[{w:s=>s.t.wit*.2,t:T('"Whatever comes at you, send it home." In one night you understand how to turn any art back on its owner: the Turnabout Art.','"别人打来什么，就还他什么。"一夜之间，你懂了如何把任何武功原封还给出招之人——反手乾坤。'),c:'gold',fx:{art:'wxstarshift',deed:T('Read the Turnabout Art at Mirror Lake Manor','于镜湖山庄参透反手乾坤')}},{w:2,t:T('It is beyond you. But even failing to understand it teaches you how other arts are built.','你看不懂。可即便看不懂，也让你明白了别家武功是怎么搭起来的。'),c:'good',fx:{skill:4,smarts:3}}]},
  {l:T('Read as much as you can, of everything','什么都读，能读多少读多少'),out:[{t:T('Shaolin, Wudang, Emei, Kunlun. By dawn your head is a crowded marketplace of arts. Some of it stays.','少林、武当、峨眉、昆仑。到天亮时，你脑子里成了一座各派武功挤得满满的集市。有些留了下来。'),c:'good',fx:{skill:5,smarts:4}}]},
  {l:T('Steal a manual','偷一本走'),out:[{t:T('You slip one under your shirt. The maid sees, says nothing, and the Nangong family never forgets a face.','你把一本塞进衣服里。侍女看见了，没吭声。可南宫家从不忘记一张脸。'),c:'bad',fx:{item:'book:bagua',align:-4,enemy:1}}]}]});

I({id:'wx_beggar',age:[12,50],once:1,w:.6,tags:['town'],ctx:s=>{const c=scene();c.npc=npc(s,{occ:7,sex:'m',age:rint(55,65)});return c},
 text:c=>T(`A dirty one-eyed old beggar with a wine gourd, ${c.npc.en}, sniffs the air over your cooking fire and drools. "Beggar’s chicken? Wrapped in lotus leaves? I would sell my staff for a leg."`,`一个背着酒葫芦的独眼老叫花子${c.npc.zh}在你的灶火边嗅了嗅，口水直流。"叫花鸡？用荷叶包的？给我一条腿，我拿青竹棒换都行。"`),
 opts:[{l:T('Cook him a real feast','给他做一桌好菜'),cost:30,out:[{w:s=>s.smarts/25+s.t.wit/5,t:T('Lotus-root duck and a soup you invent on the spot! He eats everything, licks every finger, and in gratitude teaches you a happy, roaming fist that is half dance and half joke.','荷叶鸭，外加一锅你现编的汤！他吃得一干二净，把手指舔了个遍。为了谢你，他教了你一套半是舞、半是玩笑的逍遥拳法。'),c:'gold',fx:{art:'wxcarefree',meet:'friend',bond:75}},{w:2,t:T('He eats it all, burps, and sleeps under your table. In the morning he is gone, and your stance is somehow better.','他吃光了，打了个嗝，睡在你桌底下。第二天一早人不见了，你的架势却莫名好了些。'),c:'good',fx:{skill:2,happy:3}}]},
  {l:T('Share your plain bread','分他一块干饼'),out:[{t:T('He eats it, sighs at its plainness, and shows you how to breathe while chewing. "Even this is martial arts."','他吃了，嫌太淡，叹了口气，又教你一边嚼一边吐纳。"这也是武功。"'),c:'good',fx:{qi:3,align:2}}]},
  {l:T('Shoo him away','把他赶走'),out:[{t:T('He goes. So does your chicken.','他走了。你的鸡也跟着走了。'),c:'muted',fx:{happy:-2}}]}]});

I({id:'wx_python',age:[16,60],once:1,w:.6,tags:WXW,when:s=>power(s)>=30,
 text:()=>T('A python as thick as a water jar drops from a tree and wraps around you.','一条水缸那么粗的大蟒从树上落下来，把你缠住了。'),
 opts:[{l:T('Bite it','张嘴咬它'),fight:FG(PW(.95,6),'injury',T('The great python','巨蟒'),T('a great python','巨蟒'),()=>T('the great python','巨蟒'),true),
   win:[{t:T('You bite its neck and drink until it lets go. The blood burns all the way down. When you wake, your inner energy has doubled and you are not hungry for a week.','你咬住它的脖子，一直喝到它松开。蛇血一路烧下去。醒来时内力大增，一个星期都不觉得饿。'),c:'gold',fx:{qi:12,maxHealth:3}}],
   lose:[{t:T('It squeezes until your ribs crack, then loses interest. You crawl home.','它一直勒到你肋骨咯吱作响，然后没了兴趣。你爬回了家。'),c:'bad'}]},
  {l:T('Go limp and play dead','装死'),out:[{w:1,t:T('It loosens its grip, confused. You slip out and run.','它犹豫着松开了。你溜出来就跑。'),c:'good',fx:{happy:2}},{w:1,t:T('It does not care whether you are dead.','它可不管你死没死。'),c:'bad',fx:{hurt:[10,22],cause:T('a great python','巨蟒')}}]}]});

I({id:'wx_snowlotus',only:1,
 text:()=>T('High on Tianshan, above the glaciers, a single snow lotus is blooming on an ice cliff.','天山之巅，冰川之上，一朵雪莲开在冰崖上。'),
 opts:[{l:T('Climb for it','攀上去采'),out:[{w:s=>s.t.root,t:T('You eat it on the cliff edge, petal by petal. Warmth spreads to your fingertips. Old aches you had forgotten are gone.','你在崖边一瓣一瓣把它吃了。暖意一直流到指尖。连那些早就忘了的旧伤痛都消失了。'),c:'gold',fx:{lifespan:3,cure:1,heal:30,maxHealth:3}},{w:3,t:T('The ice breaks under your hand. You fall twenty feet into soft snow, and the lotus falls after you, crushed.','冰在手底下碎了。你跌进二十尺下的软雪里，雪莲也跟着掉下来，压碎了。'),c:'muted',fx:{hurt:[8,16],cause:T('a fall on Tianshan','天山坠崖'),heal:10,lifespan:1}}]},
  {l:T('Leave it to bloom','让它开着'),out:[{t:T('You sit and watch it until your eyebrows freeze. Some things are better left where they are.','你坐着看它，直看到眉毛结了霜。有些东西，还是留在原地最好。'),c:'good',fx:{qi:5,talent:{heart:1}}}]}]});

I({id:'wx_peachisle',only:1,ctx:s=>{const c=scene();c.npc=npc(s,{occ:19,sex:'m',age:rint(55,65)});return c},
 text:()=>T('The boat leaves you on Tide-Listening Isle. The paths move when you are not looking. In the middle of the maze, a man in green plays a jade flute: the island’s master, called the Eccentric of the Eastern Sea, who despises rules and everyone who keeps them.','船把你丢在听潮岛上。你一不留神，小路就变了样。迷阵中央，一个青衫人在吹玉箫：岛主人称"东海狂客"，最瞧不起规矩，也瞧不起守规矩的人。'),
 opts:[{l:T('Answer his riddles','对答他的谜题'),out:[{w:s=>s.smarts/25,t:T('He asks about stars, poems and the Five Elements. You answer three of four. "Not stupid," he says, which from him is a hymn. He lets you study the maze for a season.','他问星象、问诗词、问五行。你答对了四题里的三题。"倒不蠢。"出自他口，这已是颂歌了。他让你在岛上研习了一季阵法。'),c:'gold',fx:{smarts:8,skill:4,talent:{wit:1}}},{w:2,t:T('"Boring," he says after the first answer, and the maze puts you back on the beach.','"无趣。"你刚答完第一题他就这么说。迷阵把你送回了海滩。'),c:'muted',fx:{smarts:2}}]},
  {l:T('Answer his flute with your own qi','以内力和他的箫声相抗'),if:s=>s.qi>=30,out:[{w:s=>s.qi/30,t:T('"Song of the Tides" rises; you hold. When it ends, he lowers the flute. "Not many can sit through that." Your inner energy has been tempered like steel.','"潮音曲"一浪高过一浪，你稳住了。曲终，他放下玉箫。"能坐着听完的人不多。"你的内力像钢一样淬过了。'),c:'gold',fx:{qi:12,fame:3}},{w:2,t:T('The flute finds a crack in your qi and pours through it. You wake on the boat, bleeding from the ears.','箫声钻进你内力的缝隙，汹涌而入。你在船上醒来，耳朵流着血。'),c:'bad',fx:{hurt:[10,22],cause:T('the Song of the Tides','潮音曲')}}]},
  {l:T('Mock the Confucian rites','痛骂礼教'),out:[{t:T('He laughs so hard he drops the flute. "Finally, someone honest!" You drink with him all night. He gives you nothing, which you later learn is what he gives his friends.','他笑得箫都掉了。"总算来了个说真话的！"你陪他喝了一夜。他什么也没送你——后来你才知道，他对朋友向来如此。'),c:'good',fx:{happy:6,meet:'friend',bond:60,smarts:2}}]}]});

I({id:'wx_lingxi',age:[18,60],once:1,w:.5,when:s=>power(s)>=50,ctx:s=>{const c=scene();c.npc=npc(s,{occ:13,sex:'m',age:rint(28,38)});return c},
 text:c=>T(`You draw on a stranger who insulted you in a wine shop. Your blade stops dead, caught between two of his fingers. He has a scar through one eyebrow and he is laughing. Later you learn his name, ${c.npc.en}: he solves other people’s troubles for the price of a drink.`,`在酒肆里，有个陌生人出言不逊，你拔刀就砍。刀锋戛然而止——被他两根手指夹住了。他一边眉毛上有道疤，正哈哈大笑。后来你才知道他叫${c.npc.zh}，专替人管闲事，只收一壶酒钱。`),
 opts:[{l:T('Ask how he did that','问他怎么做到的'),out:[{w:s=>s.t.wit*.15,t:T('"Look at the sword, not the man," he says, and spends an evening showing you. By midnight you can catch a chopstick thrown at your face. The Two-Finger Catch.','"看剑，别看人。"他说着，花了一晚上教你。到半夜，你已能夹住迎面掷来的筷子。双指夹锋。'),c:'gold',fx:{art:'wxlingxi',meet:'friend',bond:70}},{w:3,t:T('"Practice," he says, which is not an answer, and takes your wine.','"多练。"他说——这不算回答——顺手喝了你的酒。'),c:'muted',fx:{skill:2}}]},
  {l:T('Help him with his case','帮他查案'),out:[{t:T('Someone has stolen a pearl from a prince, and everyone is lying. You help him unravel it in a week, and come out with a friend and a scar.','有人偷了王爷的一颗明珠，人人都在说谎。你帮他用一个星期理清了真相，换来一个朋友和一道疤。'),c:'good',fx:{fame:5,smarts:3,meet:'friend',bond:65,hurt:[4,10],cause:T('somebody else’s mystery','别人的悬案')}}]},
  {l:T('Sheathe your blade and leave','收刀走人'),out:[{t:T('"Shame," he calls after you. "You were interesting for a moment."','"可惜，"他在你身后喊，"刚才你还挺有意思的。"'),c:'muted'}]}]});

I({id:'wx_perfume',age:[18,60],once:1,w:.6,when:s=>s.money>=200,
 text:()=>T('A note with a little paper bat is pinned to your door: "Tonight I shall come to borrow your finest treasure. — the Night Bat." The Night Bat has never failed, and never hurt anyone.','门上别着一张字条，夹着一只纸剪的蝙蝠："今夜子时，当来借君最珍爱之物。——夜蝠。"神偷夜蝠从未失手，也从未伤过人。'),
 opts:[{l:T('Guard your treasure all night','彻夜守着'),out:[{w:1,t:T('You do not sleep, do not blink, and at dawn your silver is all there. On top of it is a paper bat. He came, looked, and decided you needed it more.','你一夜没合眼，天亮时银子一两不少。上面放着一只纸蝙蝠——他来过，看过，觉得你更需要这些钱。'),c:'good',fx:{happy:4,skill:1}},{w:2,t:T('You blink once. A hundred taels are gone, and a thank-you note says it went to a flood village.','你眨了一下眼。一百两没了，留下一张谢帖，说银子送去了遭水灾的村子。'),c:'muted',fx:{money:-100,align:2}}]},
  {l:T('Leave out wine and a note','备好酒，留张字条'),out:[{t:T('In the morning the wine is drunk and your purse is heavier. "For the best wine in the county," says the note. Plus a little lesson in lightness, scrawled on the back.','早上酒被喝光了，你的钱袋反倒沉了些。字条上写："谢君一县之佳酿。"背面还草草写了几句轻功心得。'),c:'gold',fx:{money:50,happy:5,skill:3}}]},
  {l:T('Hire guards','雇人看守'),cost:40,out:[{t:T('Twelve guards. In the morning all twelve are asleep and tied with silk ribbons. Nothing is missing. He just wanted to make the point.','雇了十二个护院。早上十二个全睡着了，个个被丝带捆着。什么也没丢——他就是想让你明白一下。'),c:'muted',fx:{happy:2}}]}]});

I({id:'wx_tongmu',age:[16,45],once:1,w:.5,tags:WXW,ctx:s=>{const c=scene();c.npc=npc(s,{occ:20,sex:'f',age:9,lv:PW(1.4,20)(s)});return c},
 text:()=>T('A little girl with a voice like an old woman’s orders you to carry her up the mountain. Fast. People are chasing her. She is ninety-six and has the body of a child: the old Mistress of the Heavenly Pool Palace.','一个声音像老太婆的小女孩命令你背她上山，快。有人在追她。她九十六岁，生着孩童的身子——她就是天池宫的老宫主。'),
 opts:[{l:T('Carry her','背她上山'),out:[{w:3,t:T('She is cruel, demanding and hits you on the head whenever you slow down. She is also, between beatings, a superb teacher. Inner energy pours into you over three months on the run.','她刻薄、挑剔，你一慢下来就敲你脑袋。可挨打之余，她也是个绝顶的老师。三个月的亡命奔逃，内力源源不断地灌进你体内。'),c:'gold',fx:{qi:15,skill:4,hurt:[6,14],cause:T('the old Mistress’s temper','老宫主的脾气'),soft:1,lifespan:1}},{w:1,t:T('Her pursuers catch up. She escapes by throwing you at them.','追兵赶上来了。她把你往他们身上一扔，自己跑了。'),c:'bad',fx:{hurt:[15,30],cause:T('the old Mistress’s enemies','老宫主的仇家')}}]},
  {l:T('Refuse to carry a child who talks like that','这么说话的孩子，不背'),out:[{t:T('She looks at you with ninety years of contempt and hops away up the cliff, faster than you could ever carry her.','她用九十年的鄙夷看了你一眼，自己蹦上了悬崖，比你背着还快。'),c:'muted'}]}]});

I({id:'wx_auction',only:1,
 text:()=>T('The Coin Gang’s secret auction. Everything under heaven is for sale, and everyone in the room is lying about who they are.','通宝帮的秘密拍卖会。天下万物皆可出售，屋里每个人都在谎报身份。'),
 opts:[{l:T('Bid on a manual: Golden Bell Cover','竞拍秘籍《金钟罩》'),if:()=>!!ARTS.wxgoldbell,cost:900,out:[{w:3,t:T('You win, at a ruinous price. The manual is real.','你以惊人的价钱拍下了。秘籍是真的。'),c:'gold',fx:{item:'book:wxgoldbell'}},{w:1,t:T('You win. It is real. On the way out someone tries to rob you, and you have to fight your way home.','你拍下了，是真本。出门就有人想抢，你一路打回了家。'),c:'gold',fx:{item:'book:wxgoldbell',hurt:[6,14],cause:T('robbers after the auction','拍卖会后的劫匪')}}]},
  {l:T('Bid on a blood-sweating horse','竞拍汗血宝马'),cost:700,out:[{t:T('It is the most beautiful animal you have ever seen and it bites everyone but you.','这是你见过最漂亮的牲口。除了你，谁都咬。'),c:'gold',fx:{item:'bloodhorse',happy:5}}]},
  {l:T('Bid on "the Heshi Jade"','竞拍"和氏璧"'),cost:300,out:[{w:3,t:T('It is green glass. Very good green glass.','是绿玻璃。非常好的绿玻璃。'),c:'bad',fx:{happy:-5,smarts:2}},{w:1,t:T('A jeweller nearly faints. It is not the Heshi Jade, but it is a jade worth five times what you paid.','珠宝商差点晕过去。那不是和氏璧，可也是块价值五倍的美玉。'),c:'gold',fx:{money:1500}}]},
  {l:T('Just watch','只看不买'),out:[{t:T('You learn who is rich, who is pretending, and who is about to die. Information is the real merchandise here.','你看出了谁真有钱、谁在装阔、谁快要没命了。在这里，消息才是真正的货。'),c:'muted',fx:{smarts:3}}]}]});

I({id:'wx_guardrecruit',only:1,ctx:s=>{const c=scene();c.npc=npc(s,{occ:31,age:rint(45,60)});return c},
 text:c=>T(`The Embroidered Guard is recruiting fighters from the jianghu. Eunuch ${c.npc.en} looks you over like a horse. "The Emperor needs swords who are not afraid of sects."`,`锦衣卫在江湖上招募好手。${c.npc.zh}公公像相马一样把你上下打量。"皇上要的，是不怕什么门派的刀。"`),
 opts:[{l:T('Put on the flying-fish robe','穿上飞鱼服'),sub:T('Become an Embroidered Guard.','当锦衣卫。'),out:[{t:T('Flying-fish robe, spring saber, and the right to arrest anyone. People cross the street when they see you now.','飞鱼服、绣春刀，见谁抓谁的权。如今人们见了你都绕着走。'),c:'gold',fx:{align:-3,fame:3,f:s=>{s.job='jinyiwei';s.jobLv=0;s.jobYears=0;s.perf=55}}}]},
  {l:T('Join, and warn the sects from inside','入职，暗中给各派通风报信'),if:s=>s.align>=10,out:[{w:2,t:T('You join, and twice a year a list of names goes missing before a raid. The jianghu has a friend at court, and does not know who.','你入了职。每年总有两回，名单在抓捕前不翼而飞。江湖在朝中有了个朋友，却不知道是谁。'),c:'good',fx:{align:5,f:s=>{s.job='jinyiwei';s.jobLv=0;s.jobYears=0;s.perf=50}}},{w:1,t:T('Your first warning is traced back to you within a month.','你头一回报信，不到一个月就被查到了头上。'),c:'bad',fx:{align:5,jail:2}}]},
  {l:T('Decline','婉拒'),out:[{t:T('"A pity," says the eunuch, and writes your name in a small book. You would rather not be in his small book.','"可惜。"公公说着，把你的名字写进了一个小本子。你可不想在他的小本子上。'),c:'muted'}]}]});

/* ====================== yearly opportunities ====================== */
addOpp({id:'o_wx_swordcast',ap:1,age:[14,75],n:T('The Longquan sword-casting festival','龙泉铸剑大会'),d:T('Smiths show their best blades. Buy one, or just learn by watching.','名匠亮出得意之作。可以买一柄，也可以看看学学。'),run(s){
  if(s.money>=150){pay(s,-150);const lucky=chance(.12+s.t.luck/80);s.items.push({id:lucky?'coldsaber':'steelsword',age:s.age});
    say(s,lucky?'You buy a plain-looking blade for 150 taels. An old smith whistles: it is cold iron.':'You buy a green steel sword for 150 taels. It sings when you draw it.',lucky?'你花一百五十两买了一柄其貌不扬的刀。老铁匠吹了声口哨：是寒铁。':'你花一百五十两买了一柄青钢剑，出鞘时铮然作响。',lucky?'gold':'good')}
  else{s.skill+=trainGain(s,.4);say(s,'You cannot afford a blade, but watching the masters temper steel teaches your hands something.','剑你买不起，可看大师们淬火锻钢，你手上也多了点领悟。','good')}}});
addOpp({id:'o_wx_songlecture',ap:2,age:[12,80],n:T('A great master lectures at Mount Song','嵩山高僧公开讲武'),d:T('Hundreds come to listen. Insight, inner energy, and sometimes more.','数百人前来听讲。能长见识、长内力，有时还有别的际遇。'),run(s){
  s.qi+=qiGain(s,.6)+1;s.smarts=clamp(s.smarts+2,0,100);
  if(!s.seen.wx_goldbell&&s.t.root>=6&&chance(.25)){say(s,'After the lecture, an old monk beckons you aside.','讲武过后，一位老僧招手叫你过去。','gold');runIncident(s,INC_BY.wx_goldbell)}
  else say(s,'"Martial arts begin where the wish to win ends." You write it on your wall.','"武功始于求胜之心尽处。"你把这句话写在了墙上。','good')}});
addOpp({id:'o_wx_peachship',ap:2,age:[16,60],if:s=>!s.seen.wx_peachisle,n:T('A ship is sailing for Tide-Listening Isle','有船要去听潮岛'),d:T('The Eccentric of the Eastern Sea’s island. Few are let in, fewer let out.','东海狂客的海岛。进去的人少，出来的人更少。'),run(s){pay(s,-20);say(s,'You pay a nervous fisherman twenty taels to take you within sight of the island.','你付了二十两，一个战战兢兢的渔夫才肯把你送到望得见岛的地方。','muted');runIncident(s,INC_BY.wx_peachisle)}});
addOpp({id:'o_wx_tomb',ap:2,age:[18,60],if:s=>!s.seen.wx_swordtomb&&power(s)>=35,n:T('Rumour of a sword tomb in the red hills','传闻红石山中有剑冢'),d:T('Four sword graves, they say. Treasure hunters are already on the road.','听说有四座剑冢。寻宝的人已经上路了。'),run(s){runIncident(s,INC_BY.wx_swordtomb)}});
addOpp({id:'o_wx_hunt',ap:2,age:[14,65],n:T('The autumn hunting season opens','秋猎开围'),d:T('Game, pelts and silver. Some of the game hunts back.','有野味、皮货和银子。有些猎物也会反过来猎你。'),run(s){
  if(!s.seen.wx_python&&power(s)>=30&&chance(.3)){runIncident(s,INC_BY.wx_python);return}
  const r=fightLife(s,{name:pick([T('a wild boar','野猪'),T('a black bear','黑熊'),T('a mountain tiger','山中猛虎')]),lv:PW(.85,4)(s),beast:1},{stakes:'injury',title:T('The autumn hunt','秋猎'),cause:T('a hunting accident','打猎受伤')});
  if(r.win){const g=rint(30,90);pay(s,g);s.fame+=1;say(s,`You bring down the beast. Pelt and meat fetch ${g} taels.`,`你猎获了野兽，皮肉卖了${g}两。`,'good')}else say(s,'The beast gets away, and so, barely, do you.','野兽跑了，你也险些没跑掉。','bad')}});
addOpp({id:'o_wx_auction',ap:1,age:[20,90],if:s=>s.money>=300,n:T('The Coin Gang holds a secret auction','通宝帮秘密拍卖'),d:T('Manuals, horses, jade. Bring silver, and a false name.','秘籍、宝马、美玉。带上银子，再带个假名字。'),run(s){runIncident(s,INC_BY.wx_auction)}});
addOpp({id:'o_wx_guard',ap:1,age:[18,50],if:s=>power(s)>=70&&s.wanted===0&&s.job!=='jinyiwei'&&!isEvil(s.sect),n:T('The Embroidered Guard is recruiting','锦衣卫招募江湖好手'),d:T('Power, a salary, and a robe people fear.','有权有俸，还有一身叫人害怕的袍子。'),run(s){runIncident(s,INC_BY.wx_guardrecruit)}});
addOpp({id:'o_wx_laba',ap:2,age:[25,80],if:s=>s.fame>=40&&!s.seen.wx_taixuan,n:T('Two envoys bring a bronze token','两位使者送来铜牌请帖'),d:T('An invitation to the Stone Wall Isle. Those who refuse are not asked twice.','石壁岛的请帖。拒绝的人，不会被请第二次。'),run(s){
  say(s,'Two envoys, one fat and smiling, one thin and grim, hand you a bronze token. You decide it is wiser to accept.','两位使者，一个胖而笑，一个瘦而冷，递给你一块铜牌。你觉得还是接下为妙。','muted');runIncident(s,INC_BY.wx_taixuan)}});
addOpp({id:'o_wx_tianshan',ap:2,age:[18,70],n:T('An expedition to Tianshan','结伴远上天山'),d:T('Glaciers, thin air, and the snow lotus, if you are lucky.','冰川、稀薄的空气，运气好还有雪莲。'),run(s){
  pay(s,-30);if(!s.seen.wx_snowlotus&&chance(.5+s.t.luck/40)){runIncident(s,INC_BY.wx_snowlotus);return}
  s.qi+=qiGain(s,.8)+1;say(s,'The cold air clears your lungs and your qi. No lotus this year.','寒风洗透了你的肺腑和真气。今年没见到雪莲。','good')}});
addOpp({id:'o_wx_heroes',ap:2,age:[18,75],if:s=>s.fame>=15,n:T('A heroes’ banquet at Qunying Manor','群英庄英雄宴'),d:T('Every hero of note will be there. Fame and friends, or trouble.','有头有脸的英雄都会到场。能结交，能扬名，也能惹麻烦。'),run(s){
  if(isEvil(s.sect)&&chance(.5)){const r=fightLife(s,{name:T('the righteous heroes','正道群雄'),lv:PW(1.15,8)(s)},{stakes:'injury',title:T('Qunying Manor','群英庄'),cause:T('the heroes of Qunying Manor','群英庄群雄')});
    if(r.win){s.fame+=8;s.align=clamp(s.align-3,-100,100);say(s,'They recognise your faction’s mark. You fight your way out through the whole banquet, and the jianghu talks of nothing else for a year.','有人认出了你身上的邪派印记。你从整座宴席中杀了出去，江湖上整整议论了一年。','gold')}
    else say(s,'They recognise your faction’s mark. You are lucky to leave with your life.','有人认出了你身上的邪派印记。你能活着离开已是万幸。','bad');return}
  s.fame+=3;const p=mkPerson(s,{rel:'friend',age:rint(25,50),bond:rint(55,70),occ:pick([13,14,8])});s.people.push(p);
  say(s,`You drink with heroes from every province, and leave with a new friend, ${p.n.py}.`,`你和各省英雄痛饮一场，还结识了新朋友${p.n.cn}。`,'good')}});
addOpp({id:'o_wx_lantern',ap:1,age:[14,45],n:T('The Lantern Festival riddle fair','元宵灯谜会'),d:T('Guess riddles under the lanterns. Win prizes, or meet someone.','在花灯下猜谜。赢彩头，或者遇见一个人。'),run(s){
  if(chance(.3+s.smarts/200)){pay(s,20);s.smarts=clamp(s.smarts+2,0,100);say(s,'You solve the hardest riddle on the street and win a silver lantern.','你猜中了整条街最难的灯谜，赢了一盏银灯。','good')}
  else if(!spouseOf(s)&&chance(.4)){const p=mkPerson(s,{rel:'lover',sex:s.gender==='m'?'f':'m',age:s.age+rint(-3,3),bond:rint(50,65)});s.people.push(p);say(s,`Someone else reaches for the same riddle. ${p.n.py} laughs, and you walk the lanterns together until midnight.`,`有人和你同时伸手去揭同一条灯谜。${p.n.cn}笑了，你们一起看灯看到了半夜。`,'gold')}
  else{happy(s,4);say(s,'You guess nothing right and eat a great many sweet dumplings.','你一条也没猜中，倒吃了一肚子汤圆。','muted')}}});
